    'a_new_key_with_the_same_scopes_and_approval_policy_is_c_c8fff425' => 'Створюється новий ключ із тими самими областями доступу та правилами схвалення. Він відображається лише один раз. Поточний ключ діятиме ще 24 години, щоб системи могли перейти на новий без перерви в роботі.',
    'a_publishable_key_lets_a_page_sign_people_in_without_a_f1562297' => 'Публічний ключ дає змогу сторінці виконувати вхід користувачів без власного бекенду. Він навмисно відкритий; список дозволених джерел запобігає його використанню на інших сайтах.',
    'a_rule_names_two_or_more_roles_that_must_never_sit_with_376dbd9e' => 'Правило визначає дві або більше ролей, які не може одночасно мати одна людина. Наприклад, той, хто ініціює платіж, не повинен його також схвалювати.',
    'a_scim_endpoint_we_push_your_people_to_joins_changes_an_629f70bd' => 'Кінцева точка SCIM, куди ми надсилаємо дані користувачів. Приєднання, зміни та виходи передаються в міру їх виникнення.',
