    'list_this_environment_s_management_keys_names_scopes_ex_cee86cf8' => 'Перегляд ключів керування цього середовища: назв, областей дозволів, строку дії та останнього використання — але ніколи не значень ключів.',
    'mint_rotate_and_revoke_management_keys_never_wider_than_95fffd92' => 'Створення, ротація й відкликання ключів керування без перевищення дозволів ключа, що виконує операцію.',
    'read_the_app_and_webhook_grants_for_user_property_names_6d69f62e' => 'Перегляд дозволів застосунків і вебхуків на простори імен властивостей користувачів.',
    'grant_or_revoke_app_and_webhook_access_to_shared_user_p_3d751497' => 'Надання або відкликання доступу застосунків і вебхуків до спільних налаштувань користувачів та просторів імен приватних метаданих.',
    'list_this_environment_s_webhook_endpoints_where_they_po_50897ffc' => 'Перегляд кінцевих точок вебхуків цього середовища: адрес призначення, підписок на події та стану призупинення — але ніколи не секретів підписування.',
    'list_the_hooks_called_during_sign_in_and_token_issuance_563aad82' => 'Перегляд хуків, що викликаються під час входу й видачі токенів, та їхнього стану активності.',
    'list_the_siem_destinations_this_environment_s_audit_tra_fe43c8df' => 'Перегляд адресатів SIEM, яким передається журнал аудиту цього середовища, та їхнього стану ввімкнення.',
    'read_this_environment_s_domain_events_the_same_events_w_a994d958' => 'Читання доменних подій цього середовища — тих самих, які доставляють вебхуки — за допомогою курсора.',
    'read_this_environment_s_audit_trail_who_did_what_to_wha_3e0d9fc8' => 'Читання журналу аудиту цього середовища: хто, що, з яким об’єктом і коли зробив.',
    'register_repoint_pause_resume_re_key_and_delete_webhook_59f2b3cf' => 'Реєстрація, зміна адреси, призупинення, відновлення, зміна ключів і видалення кінцевих точок вебхуків. Новий або замінений секрет підписування відображається лише один раз.',
    'register_pause_activate_and_remove_hooks_endpoints_that_17dc8c62' => 'Реєстрація, призупинення, активація та видалення хуків — кінцевих точок, що можуть додавати твердження до токенів або відмовляти у вході.',
    'create_disable_resume_and_delete_audit_log_streams_a_ge_d507a36c' => 'Створення, вимкнення, відновлення й видалення потоків журналу аудиту. Згенерований ключ підписування відображається лише один раз.',
    'record_audit_events_your_app_s_users_cause_for_the_orga_a94adc1d' => 'Запис подій аудиту, спричинених користувачами вашого застосунку, для організацій, у яких вони відбуваються. Лише дозволи, потрібні серверній частині для надсилання подій.',
    'read_the_audit_events_your_app_sent_and_the_exports_mad_e424eabd' => 'Читання подій аудиту, надісланих вашим застосунком, та їхніх експортів, перевірка ланцюжка організації, перегляд схем і правил зберігання цих подій.',
    'start_csv_exports_of_the_audit_events_your_app_sent_the_230b66c5' => 'Запуск експорту CSV подій аудиту, надісланих вашим застосунком, — тих самих подій, які доступні в області дозволів читання, в одному файлі.',
    'define_replace_and_delete_the_schemas_audit_events_are_c37e0366' => 'Визначення, заміна й видалення схем перевірки подій аудиту та зміна строку їхнього зберігання — скорочення строку назавжди видаляє старіші події.',
    'read_the_authorization_schema_and_its_tuples_and_ask_ch_e5b3f66c' => 'Читання схеми авторизації та її кортежів, виконання перевірок і запитів списків — «Чи може цей користувач редагувати цей документ?», «Які документи він може бачити?». Лише дозволи, потрібні серверній частині застосунку для застосування правил доступу.',
    'write_and_delete_relationship_tuples_who_owns_edits_or_53581cba' => 'Запис і видалення кортежів зв’язків — хто володіє якими ресурсами вашого застосунку, редагує або переглядає їх. Запис одразу надає або відкликає доступ у застосунку.',
    'replace_the_authorization_schema_the_resource_types_and_f57d294e' => 'Заміна схеми авторизації — типів ресурсів і способу визначення кожного зв’язку. Одразу змінює результати всіх перевірок у цьому середовищі.',
    'read_the_authentication_policy_the_social_login_provide_758352e3' => 'Читання політики автентифікації, постачальників входу через соціальні мережі та декларації застарілого входу — але ніколи не секрету постачальника.',
    'change_password_mfa_and_sso_rules_self_service_sign_up_66c7cb03' => 'Зміна правил паролів, MFA та SSO, самостійної реєстрації, постачальників входу через соціальні мережі й схвалення застарілого входу.',
    'read_radar_s_mode_built_in_and_custom_rules_allow_and_d_3e27d38d' => 'Перегляд режиму Radar, вбудованих і власних правил, списків дозволених і заблокованих та оглядача рішень — чому вхід або реєстрацію дозволено, спрямовано на додаткову перевірку чи заблоковано. IP та інші адреси з рішення ніколи не розкриваються.',
    'write_reorder_and_delete_radar_rules_tune_the_built_in_254f1eff' => 'Створення, зміна порядку й видалення правил Radar, налаштування вбудованих правил, додавання та вилучення записів зі списків дозволених і заблокованих.',
    'switch_radar_between_monitor_record_only_and_enforce_bl_c3ec2073' => 'Перемикання Radar між спостереженням (лише запис) і застосуванням правил (блокування та додаткова перевірка) — увімкнення або вимкнення захисту входу в середовищі.',
    'list_the_publishable_keys_browser_apps_present_to_the_f_9a4fe3ce' => 'Перегляд публічних ключів застосунків, які браузерні застосунки передають Frontend API, та їхніх дозволених джерел.',
    'create_publishable_keys_change_which_origins_may_presen_79684ec2' => 'Створення публічних ключів застосунків, зміна джерел, які можуть їх передавати, та відкликання ключів.',
    'list_the_applications_that_trust_this_environment_as_th_61538b0b' => 'Перегляд застосунків, які довіряють цьому середовищу як постачальнику ідентифікації SAML, — але ніколи не їхніх сертифікатів.',
    'register_change_and_remove_the_applications_people_sign_6b6a4041' => 'Реєстрація, зміна й видалення застосунків, у які користувачі входять за допомогою свого облікового запису тут.',
    'read_the_hosted_sign_in_theme_and_branding_of_the_envir_c85a3622' => 'Перегляд теми й фірмового оформлення розміщеної сторінки входу середовища та його організацій.',
    'change_the_hosted_sign_in_theme_and_branding_of_the_env_bc832c7e' => 'Зміна теми й фірмового оформлення розміщеної сторінки входу середовища та його організацій.',
    'read_this_environment_s_custom_domain_and_the_dns_recor_4408e8a7' => 'Перегляд власного домену цього середовища та запису DNS, який його підтверджує.',
    'add_verify_and_remove_the_custom_domain_this_environmen_9a4835eb' => 'Додавання, перевірка й вилучення власного домену, на якому доступне це середовище.',
    'erase_a_person_for_good_gdpr_art_17_their_credentials_s_ff46c230' => 'Остаточне видалення особи (ст. 17 GDPR): її облікові дані, сеанси, членства й персональні дані видаляються, а обліковий запис псевдонімізується. Цю дію не можна скасувати.',
    'create_rename_re_permission_and_delete_roles_and_author_dca95601' => 'Створення, перейменування, зміна дозволів і видалення ролей, а також визначення ручних дозволів, з яких вони складаються. Надання ролей людям належить до `roles:write`.',
    'list_the_saml_and_oidc_connections_organizations_sign_i_8dbbb680' => 'Перегляд підключень SAML і OIDC, через які входять організації, та доменів електронної пошти, що спрямовують до них користувачів, — але ніколи не сертифікатів, секретів клієнта чи ключів підписування.',
    'create_change_enable_disable_and_delete_sso_connections_58aa8cd7' => 'Створення, зміна, увімкнення, вимкнення й видалення підключень SSO, запровадження обов’язкового SSO для організації, перевірка її поштових доменів і примусове спрямування їх на SSO. Змінює спосіб входу користувачів.',
    'list_the_directories_scim_google_workspace_microsoft_en_97350786' => 'Перегляд каталогів (SCIM, Google Workspace, Microsoft Entra), з яких синхронізуються користувачі, їхніх груп і помилок синхронізації — але ніколи не токенів bearer чи облікових даних постачальника.',
    'connect_rename_pause_re_key_and_delete_inbound_director_9cb4cce4' => 'Підключення, перейменування, призупинення, зміна ключів і видалення вхідних каталогів та зіставлення їхніх груп із ролями. Новий або замінений токен bearer SCIM відображається лише один раз.',
    'list_the_downstream_scim_targets_this_environment_pushe_2753c203' => 'Перегляд цільових систем SCIM, до яких це середовище надсилає користувачів, та стану помилок у них — але ніколи не їхніх облікових даних.',
    'register_pause_resume_and_delete_the_scim_targets_this_ca3c3bb1' => 'Реєстрація, призупинення, відновлення й видалення цільових систем SCIM, до яких це середовище надсилає дані користувачів.',
    'read_role_conflict_segregation_of_duties_rules_and_acce_8572d9a3' => 'Читання правил конфліктів ролей (розподілу обов’язків) і переглядів доступу з усіма пунктами, які потрібно підтвердити.',
    'define_switch_and_remove_role_conflict_rules_open_acces_34e40e6c' => 'Визначення, увімкнення, вимкнення й видалення правил конфліктів ролей; відкриття переглядів доступу, запис рішень і закриття переглядів — закриття застосовує всі відкликання доступу.',
    'list_the_downstream_credentials_stored_in_the_token_vau_15a080ce' => 'Перегляд облікових даних зовнішніх систем, збережених у сховищі токенів, та застосунків, які можуть отримати тимчасовий доступ до кожного з них, — але ніколи не збережених значень.',
    'store_rotate_and_revoke_downstream_credentials_and_gran_86bf996c' => 'Зберігання, ротація й відкликання облікових даних зовнішніх систем та надання або скасування права застосунку на тимчасовий доступ до них. Це не області дозволів vault.manage / vault.lease у власному токені застосунку.',
    'list_feature_flags_with_their_targeting_and_evaluate_ev_92059a92' => 'Перегляд прапорців функцій і їхніх правил націлювання та обчислення кожного прапорця для користувача в організації — те, що запитує серверна частина застосунку, коли не має токена.',
    'define_switch_retarget_and_delete_feature_flags_which_f_e64692af' => 'Визначення, перемикання, зміна націлювання й видалення прапорців функцій — які функції отримують ті чи інші користувачі та організації.',
    'list_the_third_party_providers_people_can_connect_their_1cc25b9b' => 'Перегляд сторонніх постачальників, до яких користувачі можуть підключати облікові записи, застосунків із правом тимчасового доступу до цих токенів і підключених користувачів — але ніколи не секретів клієнта чи токенів.',
    'configure_change_and_remove_pipes_grant_or_withdraw_an_f69a04e9' => 'Налаштування, зміна й видалення інтеграцій pipes, надання або скасування права застосунку на тимчасовий доступ до токенів підключених облікових записів і відключення облікового запису користувача.',
    'list_an_organization_s_recent_admin_portal_links_what_e_f1c55153' => 'Перегляд останніх посилань організації на Портал адміністратора: що кожне відкриває, хто його створив, кому надіслано та який його стан, — але ніколи не самого посилання.',
    'mint_a_one_time_admin_portal_link_that_lets_an_organiza_9371449a' => 'Створення й відкликання одноразового посилання на Портал адміністратора, яке дає ІТ-адміністратору організації змогу налаштувати SSO, домени або синхронізацію каталогів без облікового запису. Нове посилання відображається лише один раз.',
    'list_the_pending_requests_from_agents_to_act_as_one_of_67e57ec8' => 'Перегляд очікуваних запитів агентів на дії від імені користувача цього середовища (OIDC CIBA): який застосунок, від чийого імені та що запитує.',
    'deny_a_pending_approval_request_denying_grants_nothing_8b11aaea' => 'Відхилення запиту на схвалення, що очікує розгляду. Відхилення не надає жодних прав; схвалити може лише сама відповідна особа.',
