    'framework_51b7e3361e5f' => 'Ідентифікатор API [:identifier] має бути абсолютним URI з хостом і без фрагмента (RFC 8707), завдовжки щонайбільше 255 символів.',
    'framework_8038ba872fa4' => 'Область [:key] не є дійсним ідентифікатором області дозволів (RFC 6749 §3.3: друковані ASCII-символи без пробілів, лапок і зворотних скісних рисок, щонайбільше 128 символів).',
    'framework_918e4c13cded' => 'Область дозволів [:key] визначається самим сервером авторизації й не може належати API.',
    'framework_43fd205dea6a' => 'Область дозволів [:key] уже належить іншому API в цьому середовищі. Ключі областей унікальні в межах середовища, оскільки запит токена визначає область лише за її ключем.',
    'framework_632573ec7b49' => 'Застосунок [:clientId] повинен мати того самого власника, що й API, доступ до якого він контролює. Зв’язування додало б ролі й дозволи одного власника до токенів іншого.',
    'framework_f94b33602fbd' => '[:input] не є придатним джерелом. Укажіть схему та хост без шляху — наприклад https://app.acme.com або http://localhost:3000 під час розробки.',
    'framework_a934fd6a0c26' => '[:origin] використовує http, тому ключ і всі дії сторінки з ним передавалися б мережею без шифрування. Використовуйте https або під час розробки хост зворотної петлі на зразок http://localhost:3000.',
    'framework_e23a74472a6b' => 'Проєкт [:projectId] досяг ліміту середовищ свого тарифу: :limit.',
    'framework_1845262d35d9' => 'Запитані області дозволів належать кільком API (:value1). Параметром resource укажіть, для якого API призначено цей токен.',
