    'framework_4a882cbbcad9' => 'Клієнт [:clientId] автентифікується власними ключами (private_key_jwt) й не має секрету. Натомість замініть ключ у його наборі JWK.',
    'framework_fc1964a8e8c4' => 'Це останній активний секрет клієнта [:clientId]. Замініть його шляхом ротації; відкликання позбавило б клієнта можливості автентифікуватися.',
