    'every_session_that_was_opened_with_a_password_ends_incl_cf05d595' => 'Кожен сеанс, відкритий за допомогою пароля, завершиться — зокрема й ваш, якщо ви ввійшли так.',
    'every_verdict_is_recorded_and_none_is_acted_on_read_the_1b797986' => 'Кожне рішення записується, але жодне не застосовується. Перегляньте рішення, перш ніж увімкнути застосування.',
    '_part1_a_code_can_be_taken_by_a_sim_swap_or_number_port_690b2597' => ':part1 Код можна викрасти через підміну SIM-картки чи несанкціоноване перенесення номера, перехопити в телефонній мережі або виманити через переконливу підроблену сторінку входу. Це все одно набагато краще за сам пароль — увімкніть цей спосіб для людей, які не можуть використовувати застосунок автентифікації чи ключ доступу.',
    '_part1_a_logo_linked_from_another_site_told_that_site_a_dcac9b85' => ':part1 Логотип, завантажуваний з іншого сайту, повідомляв тому сайту про кожну людину, яка відкривала вашу сторінку входу. Тому розміщені сторінки тепер показують лише зображення, завантажені сюди. Завантажте логотип нижче в розділі :part2 або видаліть його, щоб прибрати це повідомлення.',
    '_part1_can_sign_in_with_passwords_or_with_this_connecti_ebadb8e1' => ':part1 може входити за паролями або через це підключення. Вимога єдиного входу відхиляє всі інші способи доступу, тож жоден уже виданий засіб доступу не зможе обійти щойно налаштованого постачальника. Більшість компаній, що підключають IdP, хочуть саме цього — але спершу прочитайте про наслідки.',
