    'catalog_description' => 'Каталог — це список, який ваші продукти показують у перемикачі застосунків. Опублікуйте кожен застосунок з адресою запуску та піктограмою, а потім виберіть, хто може його бачити. Кожен застосунок і надалі керує входом і доступом.',
