    '_part1_a_role_is_a_label_stamped_into_the_token_the_one_92a78021' => ':part1 Роль — це мітка, записана в токені. Ролі, оголошені застосунком, тут доступні лише для читання, а решту визначаєте ви. :part2 :part3 :part4 — кожен учасник також має рівно одну таку роль (Власник, Адміністратор, Розробник, Учасник або Переглядач), яка визначає, чим він може керувати в цій консолі.',
