    'a_feature_flag_is_a_switch_your_apps_ask_about_for_one_9a43d208' => 'Прапорець функції — це перемикач, стан якого застосунки перевіряють для певної особи в організації. Увімкніть його для вибраних користувачів, організацій або певного відсотка користувачів. Усі застосунки отримують однакову відповідь у полі `feature_flags` токена або від кінцевої точки оцінювання, без нового розгортання. Правило користувача має пріоритет над правилом організації, воно — над поступовим увімкненням, а те — над типовим значенням.',
    'every_sign_in_and_sign_up_in_this_environment_is_judged_083be88e' => 'Кожен вхід і реєстрація в цьому середовищі оцінюються й записуються тут від першої спроби.',
