    'catalog_invalid_icon' => 'Використовуйте піктограму розміром до 128 KiB і 512 × 512 пікселів.',
    'international_format_works_anywhere_e_g_45_1_e06a0cd1' => 'Міжнародний формат працює всюди, наприклад +45 12 34 56 78.',
    'it_gets_a_client_secret_shown_once_on_the_ne_356c8ac4' => 'Отримає секрет клієнта, який відображається лише один раз на наступному екрані.',
    'it_is_called_again_at_the_hook_point_from_the_next_matc_a4d12b55' => 'Знову викликатиметься в точці виконання хука, починаючи з наступної відповідної операції.',
    'it_stops_being_able_to_act_as_you_immediately_and_has_t_5c3d584b' => 'Негайно втрачає можливість діяти від вашого імені й має знову попросити вашого схвалення.',
    'it_stops_being_called_at_the_hook_point_the_operation_i_72937229' => 'Більше не викликатиметься в точці виконання хука. Операція, на яку він відповідав, продовжиться без нього.',
    'it_stops_working_immediately_anything_still_using_it_fa_4a9caff7' => 'Негайно припиняє діяти. Усе, що досі його використовує, не зможе ввійти.',
    'it_uses_pkce_and_gets_no_secret_nothing_to_l_f9fee647' => 'Використовує PKCE й не отримує секрету — з браузера чи телефона нема чому витекти.',
    'its_events_are_accepted_unchecked_from_now_on_or_refuse_af37acad' => 'Відтепер його події приймаються без перевірки або відхиляються, якщо ввімкнено суворий режим.',
    'its_members_can_sign_in_again_and_its_environments_resu_d369bd33' => 'Його учасники знову можуть входити, а середовища відновлюють автентифікацію.',
    'its_own_credentials_in_place_of_the_environment_s_for_t_bf11c9ef' => 'Власні облікові дані замість даних середовища для цього постачальника.',
    'key_created_paste_it_into_your_frontend_it_is_meant_to_0e59b7a5' => 'Ключ створено. Вставте його у фронтенд — він призначений бути публічним.',
    'key_rotated_copy_the_new_one_now_the_old_key_keeps_work_aedb1c3d' => 'Ключ замінено — скопіюйте новий зараз. Старий ключ діятиме ще 24 години.',
    'offers_google_github_apple_and_others_as_buttons_on_you_82b5af03' => 'Показує на сторінці входу кнопки Google, GitHub, Apple та інших постачальників для людей, які воліють використати наявний обліковий запис замість нового пароля. Налаштуйте постачальника один раз для середовища, і він буде доступний усім організаціям. Організація може використати власні облікові дані або вимкнути постачальника. Ви вводите облікові дані, а решта заповнюється автоматично. Самої адреси від постачальника ніколи не достатньо для доступу до вже наявного тут облікового запису.',
    'the_keys_your_own_code_presents_to_cbox_id_one_tab_per__a0955137' => 'Ключі, які ваш код передає Cbox ID, з окремою вкладкою для кожного типу. Секретний ключ, або ключ керування, дозволяє серверній частині керувати організаціями, учасниками, запрошеннями, ролями й застосунками одного середовища. Ключ організації викликає її API із вбудованою роллю. Публічний ключ використовується в браузерному застосунку й працює лише з дозволених джерел. Секретні ключі та ключі організації показуються лише один раз. Скопіюйте їх під час створення й негайно відкличте в разі витоку.',
    'registers_applications_that_accept_this_environment_as_d381d96e' => 'Реєструє застосунки, які приймають це середовище як постачальника ідентифікації SAML, щоб користувачі входили з наявними тут обліковими записами. Призначте кожному застосунку його організацію, щоб доступ мали лише її учасники. Без призначеної організації застосунок доступний усім користувачам середовища. Це вихідний напрямок. Для входу з корпоративним обліковим записом іншої системи використовуйте Корпоративний SSO у розділі Автентифікація.',
    'pick_the_framework_you_are_building_with_and_an_app_is_a82b6a71' => 'Виберіть фреймворк, у якому розробляєте. Буде створено застосунок із переспрямуванням на локальний сервер розробки, блоком конфігурації середовища для вставлення та кодом входу користувача. Сторінка чекає на справжній вхід. Нижче наведено кроки підготовки продукту: оформлення бренду, організації, єдиний вхід, агент, колега й виробниче середовище. Виконання позначається за фактичним станом середовища, а не вручну.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_96651d15' => 'Radar оцінює кожен вхід і реєстрацію: спроби з викраденими обліковими даними, швидкість, характерну для ботів, неможливі переміщення, нові пристрої, анонімізаційні мережі й одноразові адреси, а також ваші правила та списки дозволених і заблокованих значень. Він записує кожне рішення й після ввімкнення застосування правил блокує доступ або вимагає другий фактор. Переглядайте рішення тут перед увімкненням застосування правил і коли хтось не може ввійти.',
    'switches_your_apps_ask_about_for_one_person_in_one_orga_e232d9a9' => 'Перемикачі функцій, які застосунки запитують для певної людини в організації. Увімкніть функцію для вибраних користувачів, організацій або частини всіх користувачів. Кожен застосунок читає ту саму відповідь із токена або API.',
    'software_that_acts_on_this_environment_with_a_managemen_24a4b34d' => 'Програмне забезпечення, яке діє в цьому середовищі за допомогою ключа керування: Claude Code, Cursor, внутрішній бот або ваш бекенд. Кожне має лише надані вами області доступу й чекає на ваше схвалення там, де ви його вимагаєте.',
    'your_receiver_keeps_the_same_secret_a_64_character_hex_c0d890ee' => 'Одержувач зберігає той самий секрет. Секрет із 64 шістнадцяткових символів перетворюється на whsec_ із доданим кодуванням base64 цього шістнадцяткового рядка — "whsec_" + base64(secret). Секрет, який уже починається з whsec_, використовується без змін.',
    'organizations_users_and_active_sessions_for_every_envir_b7f36bfd' => 'Організації, користувачі й активні сеанси всіх середовищ цієї інсталяції, а також організації з найбільшою кількістю учасників. Цей огляд лише читає дані й ніколи не змінює середовище, вибране в консолі.',
    'everyone_who_can_sign_in_to_this_organization_and_the_i_e278dd18' => 'Усі, хто може входити до цієї організації, і надіслані запрошення, яких ще ніхто не прийняв. Запрошуйте людей електронною поштою; вони самостійно налаштовують вхід, тож вам ніколи не доведеться працювати з чужими паролями.',
    'let_people_sign_in_with_an_account_they_already_have_se_de3c77a6' => 'Дозвольте людям входити за допомогою наявного облікового запису. Налаштуйте постачальника один раз для середовища, і він стане доступним у всіх організаціях. Організація може використовувати власні облікові дані або вимкнути постачальника.',
    'radar_judges_every_sign_in_and_sign_up_credential_stuff_9c16eda1' => 'Radar оцінює кожен вхід і реєстрацію: спроби з викраденими обліковими даними, швидкість, характерну для ботів, неможливі переміщення, нові пристрої, мережі анонімізації, тимчасові адреси та ваші власні правила й списки. Також записує причину рішення.',
    'this_user_can_no_longer_sign_in_to_any_application_in_t_571ac0d8' => 'Цей користувач більше не може входити до жодного застосунку в цьому середовищі, а його наявні сеанси перестануть працювати під час наступного запиту. Його записи зберігаються, і ви можете знову активувати його будь-коли.',
    'evaluated_in_order_the_deny_list_the_allow_list_your_ru_00db2fea' => 'Порядок оцінювання: список блокування, список дозволів, власні правила згори вниз (вирішує перший збіг), потім вбудовані правила (вирішує найсуворіше з тих, що спрацювали). Якщо збігів немає, доступ дозволено.',
    'most_integrations_want_webhooks_instead_those_run_after_576be07b' => 'Для більшості інтеграцій варто використовувати вебхуки: вони виконуються після події й не можуть її затримати. Використовуйте hook лише тоді, коли ваша система має брати участь у рішенні під час входу або видачі токена.',
    'keys_you_create_appear_here_with_when_each_was_last_use_8c3ff766' => 'Створені ключі з’являються тут разом із часом останнього використання кожного.',
    'leave_empty_for_no_lockout_this_deployment_has_switched_d1f1a3e9' => 'Залиште порожнім, щоб не блокувати — у цьому розгортанні стандартне блокування вимкнено.',
    'let_people_sign_in_with_the_company_account_they_alread_b98aff03' => 'Дозвольте людям входити зі своїм наявним корпоративним обліковим записом замість окремого пароля тут.',
