    '_part1_sandbox_999a5fa7' => ':part1 · тестове середовище',
    '_part1_showing_the_part2_most_recent_of_part3_679247ba' => ':part1 Показані найновіші запрошення: :part2 із :part3.',
    'the_link_they_were_sent_stops_working_immediately_and_a_77389b6a' => 'Надіслане посилання негайно припиняє працювати, а ролі, які воно містило, відкликаються. Після цього можна надіслати нове запрошення.',
