    'each_link_works_until_it_expires_or_you_withdraw_it_par_d620d404' => 'Кожне посилання працює до завершення строку дії або відкликання. :part1',
    'access_to_part1_of_part2_environments_7c44f9ee' => 'Доступні середовища: :part1 із :part2',
    'this_transfers_ownership_of_the_shared_organization_rol_19e09a02' => 'Це передає право власності на спільну організацію. Ролі в кожному застосунку залишаються незмінними; ви можете втратити доступ до Cbox ID.',
    'showing_the_first_part1_search_to_reach_the_rest_9e61b9cb' => 'Кількість показаних початкових результатів: :part1. Решту знайдіть за допомогою пошуку.',
    'the_app_that_asks_4a500e90' => 'Застосунок, що надсилає запит',
    'the_app_whose_declared_roles_and_permissions_tokens_for_a1169778' => 'Застосунок, чиї оголошені ролі й дозволи містять токени для цього API. Залиште порожнім, і кожен токен міститиме ролі застосунку, який його запитав.',
    'the_app_whose_declared_roles_and_permissions_tokens_for_f9092feb' => 'Застосунок, чиї оголошені ролі й дозволи містять токени для цього API. Можна вибрати лише застосунки з цим власником: :part1.',
    'the_audience_its_tokens_name_fixed_every_token_already_a3d06aee' => 'Одержувач, указаний у токенах. Незмінний — його містить кожен уже виданий токен.',
    'the_baseline_every_organization_in_this_environment_inh_75711a2d' => 'Базові правила, які успадковує кожна організація цього середовища. Організація може вимагати суворіших правил, але не м\'якших.',
    'the_ceiling_on_this_app_s_access_narrowing_it_takes_eff_5f2865bc' => 'Верхня межа доступу цього застосунку. Її звуження діє з наступного токена. Пристрій або агент, який запитує видалену область доступу, отримає відмову, а не непомітно менші права.',
    'the_ceiling_on_this_app_s_tokens_it_can_ask__87966742' => 'Максимальний обсяг доступу токенів цього застосунку. Застосунок може запитати менше дозволів, але ніколи не більше.',
    'the_conflict_stops_being_enforced_grants_it_was_blockin_37391474' => 'Конфлікт більше не перевірятиметься. Призначення, які він блокував, знову стануть можливими.',
    'the_conflict_stops_being_enforced_immediately_and_grant_88f978ef' => 'Перевірка конфлікту негайно припиниться, а заблоковані призначення знову стануть можливими. Цю дію неможливо скасувати.',
    'the_current_client_secret_stops_working_immediately_and_030370f0' => 'Поточний секретний ключ клієнта негайно припинить дію без можливості відновлення — автентифікація всіх розгортань, що досі його використовують, почне завершуватися помилкою.',
    'the_environment_s_administrators_register_apis_and_deci_eb40bdf1' => 'Адміністратори середовища реєструють API та визначають, які їхні області доступу можуть запитувати ваші застосунки.',
    'the_facts_your_app_wrote_what_they_add_up_to_is_what_a_3240d92d' => 'Факти, записані вашим застосунком. Відповідь перевірки показує, що вони означають разом.',
    'the_key_can_do_only_what_its_scopes_allow_read_never_im_78fe4757' => 'Ключ може робити лише те, що дозволяють його області доступу. Читання ніколи не означає дозволу на запис.',
    'the_key_holds_the_built_in_role_you_choose_and_can_do_o_b7c48a4b' => 'Ключ має вибрану вбудовану роль і може робити лише те, що вона дозволяє.',
    'the_kill_switch_off_the_flag_is_off_for_everyone_whatev_90bda36f' => 'Головний вимикач. Якщо вимкнено, прапорець вимкнений для всіх незалежно від правил нижче.',
