    'the_services_of_yours_that_receive_access_tokens_and_th_8f7e35e1' => 'Ваші сервіси, які отримують токени доступу, та області доступу, що належать кожному з них. Саме ви надаєте області зареєстрованого API — ніхто не може потрапити до вашого API, просто вписавши область у застосунок.',
    'the_organization_s_own_keys_for_the_organization_api_li_86017b30' => 'Власні ключі організації для її API: перегляд проєктів і середовищ, створення середовищ, перегляд команди та запрошення учасників. Кожен ключ має вбудовану роль.',
    'these_apply_to_every_organization_in_part1_not_only_par_ac56590d' => 'Вони діють для всіх організацій у :part1, а не лише для :part2.',
