    'they_become_this_organization_s_only_owner_whoever_owns_11374c6d' => 'Ця особа стане єдиним власником організації. Поточний власник стане адміністратором.',
    'they_get_an_email_with_a_link_nothing_changes_until_the_e94c64b9' => 'Особа отримає електронний лист із посиланням. До прийняття запрошення нічого не зміниться.',
