    'they_lose_every_role_and_application_this_organization_8c05da9e' => 'Особа негайно втратить усі ролі та доступ до застосунків, надані цією організацією.',
    'this_app_belongs_to_the_platform_and_is_available_to_ev_0c69cd5f' => 'Цей застосунок належить платформі й доступний кожній організації цього середовища. Ним керує ваш оператор.',
    'this_app_holds_scopes_of_more_than_one_api_part1_part2_163d032f' => 'Цей застосунок має області доступу кількох API: :part1 :part2. Токен призначений лише для одного API за раз, тому застосунок указує потрібне параметром :part3 — запит областей доступу двох API одночасно буде відхилено.',
