    'this_deployment_has_no_turnstile_keys_cbox_id_turnstile_9ceda61f' => 'У цьому розгортанні немає ключів Turnstile (CBOX_ID_TURNSTILE_SITE_KEY), тому перевірку ввімкнути неможливо. Для позначеної реєстрації натомість потрібно підтвердити електронну адресу.',
    'this_deployment_only_texts_part1_so_numbers_in_part2_ca_6cb21f4d' => 'Це розгортання надсилає SMS лише до таких країн: :part1. Номери з наведених далі країн не отримуватимуть кодів, доки ці країни не буде додано до CBOX_ID_SMS_ALLOWED_COUNTRIES: :part2.',
