    'this_permission_is_removed_from_every_role_that_current_d88d6738' => 'Цей дозвіл буде видалено з усіх ролей, які зараз його надають. Цю дію неможливо скасувати.',
    'this_role_belongs_to_the_environment_and_applies_across_0a2b2ed6' => 'Ця роль належить середовищу й діє в усіх його організаціях — вона діє й тут, але ви не можете її змінювати.',
