    'try_a_different_search_roles_already_ticked_stay_in_thi_82c5a227' => 'Спробуйте інший пошук — уже позначені ролі залишаться в списку незалежно від введеного тексту.',
    'turn_it_on_for_a_beta_organization_a_few_users_or_a_per_bea36395' => 'Увімкніть для тестової організації, кількох користувачів або певного відсотка всіх користувачів.',
