    'type_the_organization_s_name_exactly_as_shown_to_confir_f021127d' => 'Для підтвердження введіть назву організації точно так, як показано.',
    'typed_scopes_part1_are_unowned_they_travel_as_they_are_e061e25f' => 'Вручну введені області доступу (:part1) не мають власника: вони передаються без змін і ніколи не використовують зареєстроване API як одержувача.',
    'until_an_api_is_registered_a_scope_is_just_text_on_an_a_db7d3254' => 'Поки API не зареєстровано, область доступу — це лише текст у застосунку, і кожен, хто може редагувати застосунок, може надати йому будь-яку область. Зареєструйте API, які викликають ваші застосунки, щоб їхні області доступу мали власника.',
