    'we_could_not_send_that_invitation_the_mail_server_refus_81a3f4df' => 'Не вдалося надіслати запрошення — поштовий сервер його відхилив. Нічого не створено; спробуйте ще раз або перевірте поштові налаштування розгортання.',
    'what_an_app_may_be_allowed_to_do_at_this_api_only_part1_c0ec6f18' => 'Що застосунку може бути дозволено робити в цьому API. Ці області доступу можуть мати лише власні застосунки :part1.',
    'what_an_app_may_be_allowed_to_do_at_this_api_your_own_a_94f7133a' => 'Що застосунку може бути дозволено робити в цьому API. Ваші власні застосунки можуть мати будь-які області доступу; зареєстровані організаціями — лише позначені для організацій.',
    'what_apps_ask_for_such_as_invoices_read_unique_in_this_2109e70c' => 'Те, що запитують застосунки, наприклад invoices:read. Унікальне в цьому середовищі.',
    'what_people_can_do_inside_your_apps_you_assign_roles_he_c31f1a20' => 'Що люди можуть робити у ваших застосунках. Ви призначаєте ролі тут; кожен застосунок визначає, що дозволяють його ролі.',
    'what_this_role_is_allowed_to_do_tick_a_permission_to_gr_518298cc' => 'Що дозволяє ця роль. Позначте дозвіл, щоб надати його, або зніміть позначку, щоб відкликати.',
