    'what_your_code_asks_for_and_what_the_feature_flags_clai_440d8ca1' => 'Те, що запитує ваш код і що містить поле feature_flags. Малі літери та цифри, між ними - _ або . Змінити пізніше неможливо.',
    'whatever_is_using_this_key_stops_working_immediately_th_8e55e6f5' => 'Усе, що використовує цей ключ, негайно перестане працювати. Цю дію неможливо скасувати.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_e14495d2' => 'Усе, до чого власник підключив цей ключ, негайно перестане працювати. За можливості попередьте його. Цю дію неможливо скасувати.',
    'when_somebody_creates_an_api_key_for_one_of_your_apps_i_15c6370c' => 'Коли хтось створить API-ключ для одного з ваших застосунків, він з\'явиться тут разом із власником і дозволеними діями.',
    'when_somebody_signs_out_or_an_administrator__3520d247' => 'Коли хтось виходить або адміністратор завершує його сеанси, видаляє чи деактивує людину, Cbox ID надсилає підписаний токен виходу на цю адресу безпосередньо між серверами, щоб застосунок теж міг завершити власний сеанс.',
    'where_cbox_id_sends_people_after_they_sign_out_of_this_3a65532f' => 'Місце, куди Cbox ID спрямовує людей після виходу із цього застосунку. URI, який запитує застосунок, має точно збігатися з одним із наведених тут URI, включно з кінцевою скісною рискою. Інакше Cbox ID залишає людину на власній сторінці після виходу. Залиште порожнім, якщо застосунок не перенаправляє людей після виходу.',
    'where_this_app_publishes_the_roles_it_unders_e6047562' => 'Де цей застосунок публікує підтримувані ролі, щоб їх можна було призначати тут.',
    'which_ways_in_part1_offers_besides_a_password_and_how_l_37522a30' => 'Які способи входу, крім пароля, пропонує :part1 і як довго триває сеанс. Вони однакові для всіх організацій середовища.',
    'who_belongs_to_this_organization_and_what_they_can_do_s_330bf97e' => 'Хто належить до цієї організації та що може робити. Людині, яка ще не має тут облікового запису, надсилається запрошення електронною поштою.',
    'who_gets_the_flag_when_no_rule_names_them_leave_it_off_b44a0c73' => 'Хто отримує прапорець, якщо його не визначає жодне правило. Залиште вимкненим, щоб спершу впровадити функцію для конкретних організацій або певного відсотка користувачів.',
    'whose_role_it_is_or_tick_the_box_above_to_define_it_for_970fb7fe' => 'Кому належить роль — або позначте поле вище, щоб визначити її для всіх організацій.',
    'whose_roles_and_memberships_the_review_snapshots_e7576353' => 'Чиї ролі та членства зафіксує перевірка.',
    'whose_rule_it_is_or_tick_the_box_above_to_apply_it_to_e_82370728' => 'Кому належить правило — або позначте поле вище, щоб застосувати його до всіх організацій.',
    'without_roles_everyone_who_can_sign_in_gets_whatever_an_dc1418f9' => 'Без ролей кожен, хто може ввійти, отримує доступ, який застосунок надає звичайному користувачу. Роль дає змогу один раз визначити, хто є редактором, а хто працівником підтримки, і всі підключені застосунки враховуватимуть це призначення.',
    'work_through_the_list_certify_what_is_still_needed_revo_9bcc79ab' => 'Перегляньте список: підтвердьте те, що ще потрібне, і відкличте решту.',
    'write_one_above_or_from_your_app_s_backend_in_batches_o_9ca507a7' => 'Запишіть один вище або надсилайте із сервера застосунку пакетами до 100.',
    'writes_531995e8' => 'запис',
    'you_are_the_only_owner_transfer_ownership_to_someone_el_1e7b6195' => 'Ви єдиний власник. Спершу передайте право власності іншій особі або видаліть організацію.',
    'you_can_also_part1_part2_part3_53f32513' => 'Інший варіант: :part1 :part2. :part3',
    'you_can_set_this_back_to_prefer_sso_or_both__b84203a4' => 'Ви можете будь-коли повернути налаштування «Надавати перевагу SSO» або «Доступні обидва способи»; завершені сеанси не відновляться.',
    'you_can_set_this_back_to_prefer_sso_or_both_available_a_b84203a4' => 'Ви можете будь-коли повернути налаштування «Надавати перевагу SSO» або «Доступні обидва способи»; завершені сеанси не відновляться.',
    'you_lose_access_immediately_as_its_owner_you_can_only_l_d51a2272' => 'Ви негайно втратите доступ. Як власник ви можете вийти лише після передавання права власності — спершу передайте його або видаліть організацію в Налаштуваннях.',
    'you_lose_access_to_this_organization_and_its_apps_immed_47fdba25' => 'Ви негайно втратите доступ до цієї організації та її застосунків. Адміністратор може запросити вас знову.',
    'your_app_s_own_access_model_resource_types_the_relation_3dddc87d' => 'Власна модель доступу застосунку: типи ресурсів, зв’язки для кожного типу та їхнє успадкування. Застосунок записує кортежі, які визначають, хто з чим пов’язаний, і перевіряє доступ під час кожного запиту.',
    'your_authentication_policy_still_applies_password_stren_84825ce9' => 'Ваша політика автентифікації залишається чинною: надійність пароля, перевірка витоків, підтвердження електронної адреси, обмеження частоти запитів і захист від ботів.',
    'your_own_api_you_choose_scope_by_scope_which_of_its_sco_6f77f332' => 'Ваше власне API. Для кожної області доступу ви визначаєте, чи можуть її запитувати застосунки, зареєстровані організаціями.',
    'your_sign_in_page_gets_a_create_an_account_link_and_app_8a665905' => 'На сторінці входу з\'явиться посилання «Створити обліковий запис», а застосунки зможуть спрямовувати користувачів безпосередньо на реєстрацію через :part1.',
    'keys_your_browser_side_app_presents_to_the_frontend_api_ff8c1e2c' => 'Ключі, які ваш браузерний застосунок передає до Frontend API. Вони входять до JavaScript-пакета; захист забезпечує список дозволених джерел, а не сам ключ.',
    'leave_empty_for_this_deployment_s_default_of_part1_f391c886' => 'Залиште порожнім, щоб використати типове значення розгортання :part1.',
    'leave_empty_for_this_install_s_default_value_fda04f89' => 'Залиште порожнім, щоб використати типове значення інсталяції. Типове значення (хвилини): :value0. Межа, встановлена оператором (хвилини): :value1.',
    'let_your_apps_declare_the_roles_they_understand_those_a_719f1d4a' => 'Нехай застосунки оголошують підтримувані ролі — вони автоматично з\'являться тут.',
