    'snapshots_every_admin_support_role_each_role_held_acros_351f6f6d' => 'Створює знімок усіх ролей адміністрування й підтримки, що діють у всьому середовищі, як пунктів для підтвердження або відкликання. Відкликання забирає роль у всіх організаціях одночасно.',
    'snapshots_every_current_role_assignment_and_membership_f56eb372' => 'Фіксує всі поточні призначення ролей і членства в одній організації як елементи для підтвердження або відкликання.',
