    'its_rules_go_with_it_apps_asking_for_its_key_get_off_fr_aacd29e9' => 'Його правила також видаляються. Застосунки, що запитують його ключ, відтепер отримуватимуть вимкнений стан; уже видані токени міститимуть його до завершення строку дії.',
    'its_scopes_go_with_it_apps_that_held_them_keep_them_as_bf31a699' => 'Його області доступу також видаляються. У застосунках вони залишаться вручну введеними областями, що більше не діють для цього API; уже видані токени працюватимуть до завершення строку дії.',
    'keys_for_an_environment_s_management_api_run_one_enviro_6197b6d2' => 'Ключі для API керування середовищем: керуйте організаціями, учасниками, запрошеннями, ролями й застосунками одного середовища зі свого бекенду. Кожен ключ має явно визначені області доступу.',
    'roles_and_permissions_arrive_in_the_access_token_as_two_0107aa88' => 'Ролі та дозволи в токені є знімком стану на певний момент. Перед кожною захищеною дією отримайте актуальне рішення про доступ від Cbox ID та перевірте у своєму застосунку доступ до конкретного ресурсу. Сам вміст токена не відображає подальше відкликання доступу:',
    'your_own_sign_in_methods_and_active_sessions_a_passkey_2bf79cbb' => 'Ваші способи входу й активні сеанси. Ключ доступу — найбезпечніший і найшвидший варіант: пристрій розблоковує його відбитком пальця або розпізнаванням обличчя, і не залишається пароля, який можна викрасти фішингом.',
    'every_action_is_accepted_as_your_app_sends_it_add_a_sch_fce48faa' => 'Кожна дія приймається в тому вигляді, в якому її надсилає застосунок. Додайте схему для дії, щоб її події перевірялися під час отримання. Узгодженість журналу забезпечується під час запису події, а не тоді, коли хтось її читає.',
    'every_api_key_sitting_in_an_app_s_config_or_environment_975161a8' => 'Кожен ключ API у конфігурації застосунку або файлі середовища — це ключ, який ви не можете централізовано замінити чи швидко відкликати. Тут він зберігається зашифрованим, доступ надається окремо кожному застосунку, а відкликати його можна одним натисканням.',
    'it_stops_appearing_as_a_button_and_its_credentials_are_120d1fa5' => 'Кнопка більше не відображатиметься, а облікові дані буде видалено. Люди, які входили через цього постачальника, збережуть свої облікові записи й зможуть надалі користуватися паролем. Щоб зберегти облікові дані, вимкніть постачальника замість видалення.',
    'the_mirror_image_cbox_id_pushes_your_people_into_the_ot_19c0ed40' => 'Зворотний напрямок: Cbox ID передає ваших людей до інших SaaS-продуктів, якими користується компанія, через їхні кінцеві точки SCIM. Одне місце для надання й відкликання доступу замість окремої панелі адміністрування кожного постачальника.',
    'creates_the_organization_its_owner_its_first_product_an_79cca112' => 'Створює організацію, її власника, перший продукт і робоче середовище цього продукту. Власник отримує електронною поштою посилання для встановлення власного пароля — ви не вибираєте пароль замість нього.',
    'today_somebody_adds_and_removes_people_here_by_hand_con_01774e72' => 'Зараз хтось вручну додає й видаляє тут людей. Підключіть каталог, який ваша компанія вже веде, і обидві дії виконуватимуться автоматично — включно з видаленням, про яке найчастіше забувають.',
    'every_token_it_issued_is_revoked_now_and_no_new_sign_in_e0dca49c' => 'Усі видані ним токени зараз відкликаються, і його більше не можна використовувати для нового входу. Застосунок, який самостійно перевіряє токени, перестане приймати їх після завершення строку дії, не пізніше завершення самого сеансу.',
    'while_you_are_migrating_off_another_system_your_app_can_a0c796b9' => 'Під час переходу з іншої системи застосунок може вказати у своєму маніфесті поруч із ролями, де працює старий вхід. Ця інформація з’явиться тут для вашого схвалення, перш ніж почне щось робити.',
    'write_one_to_allow_challenge_or_block_on_what_you_know_9a9a03a4' => 'Створіть правило, яке на основі знань про користувачів дозволятиме доступ, вимагатиме додаткової перевірки або блокуватиме його. Вимагайте додаткової перевірки для входів із країн, де ви не працюєте, або звільніть офісну мережу від правил частоти.',
    'verifying_a_domain_you_own_acme_com_lets_cbox_id_recogn_7a9ae408' => 'Підтвердження власного домену, наприклад acme.com, дає змогу Cbox ID розпізнавати ваших людей за електронною адресою й одразу спрямовувати їх до вашого постачальника, без вибору правильної кнопки входу.',
    'an_identity_provider_that_imports_service_provider_meta_9cbb9457' => 'Постачальник ідентичності, який імпортує метадані постачальника послуги, використовує цю URL-адресу замість окремого введення ідентифікатора сутності та URL ACS. Вона працює ще до заповнення налаштувань на боці постачальника ідентичності.',
    'this_cannot_be_undone_their_credentials_memberships_and_0d29eed0' => 'Цю дію неможливо скасувати. Облікові дані, членства й персональні дані буде видалено, а обліковий запис — псевдонімізовано. Якщо людина є єдиним власником організації, спочатку передайте право власності.',
    'you_act_as_this_person_in_their_session_with_their_acce_36ea7fac' => 'Ви дієте як ця людина, у її сеансі та з її правами доступу. Доступ обмежений 30 хвилинами й лише читанням там, де консоль може це забезпечити. Кожен запит записується на ваше ім’я.',
    'suspension_is_the_only_thing_this_page_changes_and_it_i_4b1a3610' => 'Призупинення — єдина зміна, яку вносить ця сторінка, і її можна скасувати. Вибір і відкриття середовища змінюють лише вигляд консолі; у жодному середовищі нічого не змінюється.',
    'right_now_people_sign_in_with_credentials_held_here_con_4538c692' => 'Зараз люди входять з обліковими даними, які зберігаються тут. Підключіть свого постачальника, щоб вони користувалися наявним корпоративним обліковим записом і втрачали доступ тут одразу після його вимкнення там.',
    'no_new_secret_is_issued_from_the_next_attempt_retries_i_eba13c7b' => 'Новий секрет не видається. Починаючи з наступної спроби, включно з повторними, доставки міститимуть заголовки іншої схеми. Неоновлений одержувач відхилятиме кожну з них.',
    'send_this_single_use_link_to_whoever_runs_their_identit_ecdd3fd5' => 'Надішліть це одноразове посилання адміністратору їхнього постачальника ідентичності, якщо він не отримав його електронною поштою. До завершення строку дії воно працює без облікового запису. Скопіюйте зараз — посилання показується лише один раз.',
    'what_software_in_this_environment_is_waiting_for_a_pers_7aa0659a' => 'Програмне забезпечення в цьому середовищі, яке чекає на дозвіл людини. Агент, ключ якого потребує схвалення, зупиняється й запитує людину, яка створила ключ. Відповідайте тут або з телефона.',
    'an_organization_is_where_users_sign_in_methods_and_role_ae379847' => 'Організація об’єднує користувачів, способи входу й ролі. Створіть її вище або налаштуйте першу організацію та адміністратора середовища на сторінці «Середовища».',
    'add_them_to_one_below_to_grant_access_inside_it_or_if_y_386e5f3c' => 'Додайте цю людину до однієї з організацій нижче, щоб надати їй доступ усередині неї. Якщо застосунки не мають власного поділу на організації, надайте роль адміністрування й підтримки, яка діє в усьому середовищі.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_caea5beb' => 'Роль адміністрування й підтримки надається вашим працівникам на все середовище. Вона діє в кожній організації, а адміністратори організацій не можуть її бачити чи змінювати.',
    'requests_appear_here_on_their_own_when_an_app_or_agent_2ee57630' => 'Запити з’являються тут автоматично, коли застосунку або агенту потрібне ваше схвалення для дій від вашого імені. До того часу нічого робити не потрібно. Якщо з’явиться запит, якого ви не ініціювали, відхиліть його.',
    'text_messages_are_the_weakest_second_step_so_fad83e4a' => 'SMS — найслабший другий фактор: той, хто заволодіє вашим номером телефону, отримуватиме ваші коди. Віддавайте перевагу застосунку-автентифікатору або ключу доступу, а SMS використовуйте лише за відсутності цих можливостей.',
    'your_environment_s_default_brand_the_hosted_sign_in_s_l_aae9270b' => 'Типове оформлення середовища: вигляд розміщеної сторінки входу, логотип і favicon, а також назва й відправник, яких бачать користувачі. Кожна організація успадковує ці налаштування, якщо не задає власні.',
    'organization_detail_in_the_target_environment_members_s_caef589f' => 'Відомості про організацію в цільовому середовищі: учасники, SSO, домени, права доступу й остання активність. На цій сторінці можна змінити лише стан організації.',
    'every_organization_on_this_install_open_one_to_walk_its_f0bd9340' => 'Усі організації цієї інсталяції. Відкрийте одну, щоб переглянути її продукти й середовища. Призупинення завершує сеанси її учасників і зупиняє автентифікацію в усіх середовищах, які їй належать.',
    'your_app_sends_these_one_call_per_batch_of_events_each_42f272f6' => 'Ці події надсилає застосунок: один виклик на пакет, а кожна подія вказує організацію, де вона сталася. У міру надходження вони з’являються тут і в адміністраторів цієї організації.',
    'the_whole_environment_offers_it_on_every_sign_in_page_c_6d75dee5' => 'Він доступний на всіх сторінках входу в усьому середовищі. Виберіть організацію, щоб налаштувати її власного постачальника, який замінить постачальника середовища на сторінці цієї організації.',
    'claude_code_opens_your_browser_to_sign_in_here_and_asks_a86b6b5e' => 'Claude Code відкриває браузер для входу тут і запитує, що ви дозволяєте. Немає ключа, який потрібно зберігати в безпеці. Будь-який клієнт MCP, що входить через OAuth, працює з цією URL-адресою так само.',
    'one_organization_on_this_install_its_team_its_projects__42711bef' => 'Один робочий простір цієї інсталяції: його команда, проєкти й усі середовища цих проєктів. Призупинення завершує сеанси учасників і зупиняє автентифікацію в усіх цих середовищах.',
    'environment_wide_anyone_with_an_account_in_this_environ_c60d926c' => 'На рівні всього середовища: будь-хто з обліковим записом у цьому середовищі, у будь-якій організації, може ввійти до застосунку. Вкажіть організацію, якщо не плануєте настільки широкий доступ.',
    'letting_your_people_sign_in_with_entra_id_okta_or_googl_10c80076' => 'Вхід через Entra ID, Okta або Google Workspace доступний у тарифі Enterprise. Зверніться до команди, яка супроводжує ваш обліковий запис, щоб увімкнути його для цієї організації.',
    'where_you_are_signed_in_what_can_act_as_you_and_what_ha_874bdb24' => 'Де ви ввійшли, що може діяти від вашого імені та що відбувалося з обліковим записом. Якщо побачите щось незнайоме, завершіть відповідний сеанс і змініть пароль.',
    'how_many_people_signed_in_and_how_often_your_apps_calle_bc3b092f' => 'Скільки людей входило та як часто застосунки викликали API за останні 30 днів. Ці дані допомагають бачити навантаження й помічати аномалії; це не рахунок.',
    'this_user_owns_or_administers_an_organization_and_those_941764ef' => 'Цей користувач володіє організацією або адмініструє її, тому вхід від його імені заборонено. Доступ до такого облікового запису міг би надати тривалий контроль над організацією тому, хто це зробить.',
    'api_keys_your_apps_and_agents_present_to_other_services_ab18c348' => 'Ключі API, які застосунки й агенти надають іншим сервісам. Кожне значення зберігається зашифрованим, передається лише дозволеним застосункам і ніколи не показується знову після збереження.',
    'apps_asking_to_act_on_one_of_your_users_behalf_each_use_4583b737' => 'Застосунки, які просять діяти від імені одного з користувачів. Кожен користувач схвалює власні запити. Відхиляйте запит тут лише тоді, коли він схожий на зловживання; відмову буде записано в журналі аудиту.',
    'how_often_to_pull_and_which_of_the_hr_system_s_own_fiel_54dd88fe' => 'Як часто отримувати дані та які власні поля HR-системи копіювати для кожної людини, наприклад центр витрат або місце розташування. Зміна полів робить наступний запуск повним.',
    'links_handed_to_this_organization_s_it_administrator_th_65719b81' => 'Посилання, передані ІТ-адміністратору цієї організації, які ще надають доступ. Відкликання посилання негайно припиняє його дію; налаштування, вже виконані через нього, залишаються.',
    'requests_from_agents_asking_to_act_on_a_user_s_behalf_a_c8d607b8' => 'Запити агентів на дії від імені користувача з’являються тут у міру надходження. Кожен користувач схвалює власні запити; ця сторінка призначена для відхилення тих, що схожі на зловживання.',
    'when_every_condition_holds_radar_takes_this_rule_s_acti_1e685d20' => 'Коли виконано ВСІ умови, Radar застосовує дію цього правила й не перевіряє наступні. Правила перевіряються після списків дозволів і блокування та перед вбудованими правилами.',
    'the_audit_events_your_app_sends_about_the_organizations_19cde284' => 'Події аудиту, які застосунок надсилає про всі організації, що обслуговує, від найновіших. Події кожної організації утворюють власний ланцюжок хешів.',
    'everything_your_organization_has_set_up_and_what_is_lef_2eaad20f' => 'Усе, що організація вже налаштувала, і те, що ще потрібно зробити. Контрольний список стежить за фактичним станом: крок автоматично позначається завершеним, щойно його справді виконано.',
    'as_an_administrator_add_an_authenticator_app_935b1e4e' => 'Як адміністратор додайте також застосунок-автентифікатор або ключ доступу. Заволодіння номером телефону дає змогу отримувати ваші SMS, тому вони не можуть бути єдиним другим фактором.',
    'deleting_this_organization_tears_down_every_project_and_0d442c8e' => 'Видалення цієї організації знищує всі її проєкти й середовища. Щоб захистити діючих постачальників ідентичності, цю операцію не можна виконати самостійно. Для продовження зверніться до підтримки.',
    'they_lose_access_to_every_platform_page_on_this_install_0e71b790' => 'Користувач негайно втрачає доступ до всіх сторінок платформи в цій інсталяції, а його наявні сеанси припинять працювати під час наступного запиту. Ви можете знову активувати його тут.',
    'verified_domains_route_people_to_your_own_identity_prov_127a9e78' => 'Підтверджені домени спрямовують людей до вашого постачальника ідентичності; ця функція входить до тарифу Enterprise. Зверніться до команди, яка супроводжує ваш обліковий запис, щоб увімкнути її для цієї організації.',
    'a_permission_is_one_thing_a_role_is_allowed_to_do_creat_522b0034' => 'Дозвіл визначає одну дію, яку може виконувати роль, наприклад створення рахунків або читання звітів. Тут можна створювати власні дозволи без коду, а потім об’єднувати їх у ролі. Застосунки також можуть автоматично реєструвати свої дозволи, щоб список відповідав правилам, які вони справді застосовують. Створені вами дозволи належать вам. Дозволи, якими ділиться середовище, можна використовувати, але не змінювати.',
    'the_password_rules_lockout_two_factor_requirement_and_s_6d5c4102' => 'Правила паролів, блокування, обов’язкового другого фактора й єдиного входу, що діють під час кожного входу. Для всього середовища також визначаються доступність ключів доступу та посилань для входу й тривалість сеансу. Середовище задає базові правила, які успадковують усі організації. Організація може посилити правила паролів і другого фактора, але не послабити їх.',
    'what_agents_in_this_environment_are_waiting_for_a_perso_8f2ea5c0' => 'Дії, для яких агенти цього середовища очікують дозволу людини. Агент, чий ключ вимагає схвалення дії, зупиняється й запитує людину, яка створила ключ. Вона може відповісти з телефона або тут. Будь-який адміністратор середовища може відхилити підозрілий запит. Нижче наведено запити застосунків діяти від імені користувачів, які кожен користувач схвалює особисто.',
    'their_sessions_and_tokens_are_revoked_their_passkeys_se_78603573' => 'Сеанси й токени цієї особи відкликаються. Видаляються її ключі доступу, другі фактори, членства, призначення ролей, API-токени, секрети у сховищі, пристрої та всі збережені копії її даних. Від облікового запису залишається лише псевдонімізований, вимкнений запис. Застосунки, які синхронізують звідси людей, отримують вказівку видалити цю особу. Журнал аудиту зберігає непрозорий ідентифікатор, а не ім’я чи адресу.',
    'anything_you_approved_including_a_device_or_a_command_l_eea3fafc' => 'Усе, що ви схвалили, зокрема пристрої чи інструменти командного рядка, з яких ви ввійшли.',
    'anything_your_own_systems_need_to_keep_against_this_org_c911b38e' => 'Дані, які вашим системам потрібно зберігати для цієї організації. Рядки без ключа пропускаються.',
    'asked_after_your_own_rules_every_one_that_fires_is_reco_8f7f4b96' => 'Оцінюються після ваших правил. Кожне правило, що спрацювало, записується; рішення визначає найсуворіше.',
    'delivery_resumes_entries_written_while_it_was_off_are_s_c6e7d5a4' => 'Надсилання відновиться. Записи, створені під час зупинки, залишаються в черзі й будуть надіслані з наступним пакетом.',
    'delivery_stops_immediately_and_the_stored_credential_is_735dadec' => 'Надсилання негайно припиниться, а збережені облікові дані буде знищено. Журнал аудиту залишиться без змін.',
    'every_link_between_cbox_id_and_another_system_in_one_pl_0376dee4' => 'Усі зв’язки між Cbox ID та іншими системами в одному місці: єдиний вхід, вхід із соціальним обліковим записом, синхронізація каталогів і HR-системи, вихідне керування обліковими записами, SAML-застосунки, вебхуки, хуки, потоки журналів і канали даних. Каталог запускає налаштування будь-якого типу: кожна картка відкриває відповідну сторінку. Список з’єднань показує всі наявні зв’язки та їхній стан, спочатку ті, що мають помилки.',
    'every_way_a_person_can_sign_in_here_password_passkeys_m_1abc176e' => 'Усі способи входу — пароль, ключі доступу, посилання для входу, соціальний обліковий запис, корпоративний SSO і другий фактор — з інформацією про ввімкнення та місце зміни налаштувань. Більшість визначає середовище, а SSO-з’єднання належать окремим організаціям. Якщо спосіб вимкнено або обмежено на рівні інсталяції, сторінка повідомляє про це й називає відповідне налаштування.',
    'an_agent_is_any_software_that_acts_on_this_environment_05aebde2' => 'Агент — це будь-яке програмне забезпечення, що діє в цьому середовищі з ключем керування: AI-асистент на кшталт Claude Code чи Cursor, внутрішній бот або ваша серверна частина. Надайте кожному окремий ключ лише з потрібними областями доступу. Визначте дії, що потребують схвалення, і відкличте ключ, щойно агент завершить роботу або щось викличе підозру.',
    'an_api_is_a_service_of_yours_that_receives_access_token_2747c516' => 'API — це ваша служба, яка отримує токени доступу, наприклад https://api.example.com. Зареєструйте її з областями доступу, які вона розпізнає, щоб мати змогу їх надавати. Ви визначаєте, які області можуть запитувати застосунки, зареєстровані організаціями цього середовища. Токен для API містить його адресу як цільову аудиторію, яку перевіряє ваша служба.',
    'how_the_audit_trail_leaves_cbox_id_a_scheduled_export_s_3da9deb4' => 'Як журнал аудиту передається з Cbox ID: запланований експорт надсилає нові записи до SIEM або архіву кожні п’ять хвилин. Щоденне завдання зберігання створює контрольну точку, не видаляючи даних. Тут можна отримати історію аудиту особи для запиту на доступ за GDPR або в консолі середовища перевірити роботу експорту.',
    'create_one_on_platform_environments_and_its_counts_appe_2e1a2d8f' => 'Створіть середовище в розділі Платформа › Середовища, і його показники з’являться тут.',
    'every_environment_on_this_install_and_how_much_of_the_e_1d09cf29' => 'Усі середовища цієї інсталяції та частка кожного в загальному обсязі',
    'every_queue_this_install_sends_background_work_through_562c4113' => 'Усі черги фонових завдань цієї інсталяції та час очікування найстарішого завдання в кожній із них',
    'every_usage_counter_for_this_window_and_the_raw_metric_22633817' => 'Усі лічильники використання за цей період та початкові ключі відповідних метрик',
    'find_an_organization_or_a_user_across_every_environment_e71f4ea0' => 'Знайдіть організацію чи користувача в усіх середовищах, а не лише у вибраному в консолі.',
    'one_long_running_process_php_artisan_queue_autoscale_st_9e4a3b67' => 'Один тривалий процес, php artisan queue:autoscale, запускає та зупиняє робочі процеси, які виконують завдання з черги.',
    'account_menu_value0_6ab6a9a2' => 'Меню облікового запису — :value0',
    'acme_inc_ee60673d' => 'Acme Inc.',
    'disconnect_value0_1d09db11' => 'Відключити :value0?',
