    'remove_value0_b8b38a7a' => 'Вилучити :value0?',
    'rename_value0_b709cc6f' => 'Перейменувати :value0',
    'value0_not_included_in_this_organization_s_p_a6447bb1' => ':value0 Не включено в тариф цієї організації.',
    'no_claimed_domain_matches_that_try_part_of_the_domain_w_1212eb45' => 'Немає відповідного заявленого домену. Спробуйте частину домену без @.',
    'no_connections_match_that_name_try_a_different_search_t_6555c50e' => 'Немає підключень із такою назвою. Спробуйте інший пошуковий запит.',
    'no_directory_matches_that_name_try_a_different_search_t_bfc6957c' => 'Немає каталогу з такою назвою. Спробуйте інший пошуковий запит.',
    'no_endpoint_url_matches_that_search_try_a_different_one_45378b36' => 'Немає URL кінцевої точки, що відповідає запиту. Спробуйте інший запит.',
    'no_entry_matches_those_filters_try_a_broader_term_or_cl_afd8d040' => 'Немає записів, що відповідають цим фільтрам. Спробуйте загальніший запит або приберіть фільтр.',
    'no_log_stream_matches_that_name_try_a_different_search_ac9bbc7c' => 'Немає потоку журналів із такою назвою. Спробуйте інший запит.',
    'no_outbound_connection_matches_that_name_try_a_differen_2fb976c3' => 'Немає вихідного підключення з такою назвою. Спробуйте інший запит.',
    'everything_your_people_see_of_your_brand_on_one_page_th_9d98e332' => 'Усі елементи бренду, які бачать користувачі, на одній сторінці: логотип, favicon, кольори, шрифт і заокруглення хостованої сторінки входу з попереднім переглядом наживо, а також назва продукту, відправник листів і вітальний лист. Налаштуйте їх один раз для всього середовища, щоб усі організації успадкували значення, або задайте організації власний вигляд на вкладці Оформлення бренду.',
    'each_project_in_your_organization_has_its_own_plan_and__0a007c9c' => 'Кожен проєкт організації має власний тарифний план і ліміт середовищ. Вони показані тут поруч із використанням за цей місяць: організації, оплачувані з’єднання єдиного входу та входи. Ціна враховує щомісячних активних користувачів і корпоративні з’єднання, як-от SSO та SCIM. У тестових середовищах плата за з’єднання не стягується.',
    'every_api_key_the_people_in_this_organization_have_crea_51e4cae3' => 'Усі API-ключі, створені людьми цієї організації для її застосунків: власник, застосунок, дозволені дії та останнє використання. Ключ може лише те, що може його власник, і припиняє працювати після виходу власника з організації. Відкликайте ключі, що потрапили до сторонніх або більше не використовуються. Кожна людина створює власні ключі в розділі Мій обліковий запис.',
    'while_you_move_off_another_system_an_app_can_ask_for_th_c182528e' => 'Під час переходу з іншої системи застосунок може попросити перевірити електронну адресу й пароль людини, якої ще немає в Cbox ID, у старій кінцевій точці входу. Перевірте її перед схваленням. Прийнята людина створюється тут і більше не надсилається до старої системи. Якщо ж стара кінцева точка не працює, люди, яких ще не перенесено, не зможуть увійти.',
    'the_audit_events_your_app_sends_about_each_organization_a385fa1d' => 'Події аудиту, які застосунок надсилає для кожної організації, що користується продуктом: хто, що й коли зробив у продукті. Вони зберігаються окремо для кожної організації в ланцюжку хешів і показуються її адміністраторам. Використовуйте їх, коли організація просить журнал аудиту свого облікового запису. Визначте схеми, щоб події мали узгоджену структуру.',
    'no_future_lease_can_open_this_secret_revocation_is_imme_5b330536' => 'Жоден майбутній тимчасовий дозвіл доступу не зможе відкрити цей секрет. Відкликання діє негайно й назавжди.',
    'no_live_agents_revoked_and_expired_keys_stay_listed_for_8dd5437a' => 'Немає активних агентів. Відкликані ключі та ключі зі строком дії, що минув, залишаються в списку для обліку.',
    'no_permissions_it_identifies_its_holder_and_nothing_mor_80cf422c' => 'Без дозволів — лише ідентифікує власника',
    'nothing_changes_for_anybody_until_this_is_on_test_a_sig_9eb3389b' => 'Поки це не ввімкнено, ні для кого нічого не зміниться. Спочатку перевірте вхід.',
    'only_a_hash_is_stored_if_it_is_lost_revoke_it_and_creat_6e39a401' => 'Зберігається лише хеш. Якщо втратите ключ, відкличте його й створіть новий.',
    'only_the_apps_listed_here_can_lease_this_secret_everyth_3afb49f2' => 'Лише перелічені тут застосунки можуть отримати тимчасовий доступ до цього секрету. Усі інші запити відхиляються.',
    'every_other_device_holding_a_session_as_you__a01280d4' => 'Ваші сеанси на всіх інших пристроях припинять працювати під час наступного запиту. На цьому пристрої ви залишитеся в системі.',
    'no_members_in_this_organization_yet_nobody_can_sign_in_d0c78702' => 'У цій організації ще немає учасників. Ніхто не зможе ввійти до неї, доки когось не запросять або не додадуть через підготовку облікових записів.',
    'no_password_is_set_here_they_get_a_sign_in_link_by_emai_5e488804' => 'Тут пароль не встановлюється. Користувач отримає посилання для входу електронною поштою та вибере спосіб входу.',
    'each_step_is_measured_from_live_state_so_the_guide_alwa_e7f5c55e' => 'Кожен крок оцінюється за поточним станом, тому посібник завжди показує фактичний стан цієї організації.',
    'copy_the_key_now_and_hand_it_to_the_agent_only_a_hash_i_fb10c803' => 'Скопіюйте ключ зараз і передайте агенту. Зберігається лише хеш, тому ключ показується лише цього разу.',
    'the_email_domains_this_organization_owns_each_proved_wi_02a41e13' => 'Домени електронної пошти цієї організації, кожен підтверджений DNS TXT-записом. Після перевірки можна ввімкнути обов’язкове спрямування на SSO: усі з адресою в цьому домені використовуватимуть корпоративне SSO-з’єднання замість пароля. Перевірте всі домени, у яких користувачі мають адреси, перш ніж покладатися на єдиний вхід.',
    'your_app_s_own_access_model_resource_types_like_documen_24105154' => 'Власна модель доступу застосунку: типи ресурсів, як-от документи й папки, відносини, як-от власник, редактор і читач, та їх успадкування. Наприклад, читачі папки можуть читати всі документи в ній. Застосунок записує, хто як пов’язаний із ресурсами, і для кожного запиту перевіряє, чи може користувач редагувати документ. Відповідь визначає схема.',
    'this_environment_serves_an_mcp_server_the_standard_way_eb9faa22' => 'Це середовище поряд із REST API надає MCP-сервер — стандартний спосіб виклику інструментів AI-асистентами. Вставте адресу й ключ керування в Claude Code, Cursor або інший MCP-клієнт. Агент зможе виконувати лише дії, дозволені областями доступу ключа, з такими самими перевірками й журналом аудиту, як у консолі.',
    'a_key_lets_your_own_scripts_and_integrations_call_an_ap_4edbc37d' => 'Ключ дозволяє вашим скриптам та інтеграціям викликати API застосунку від вашого імені без входу. Він може лише те, що можете ви в цьому застосунку: якщо ваш доступ обмежено, ключ також його втрачає. Ключ показується лише один раз. Скопіюйте його під час створення й негайно відкличте в разі витоку або завершення використання.',
    'provisioning_stops_and_the_group_mappings_go_with_it_th_b562bdb6' => 'Автоматичне керування обліковими записами припиниться, а зіставлення груп буде видалено. Створені користувачі залишаться.',
    'provisioning_stops_immediately_and_every_group_mapping_7a323b54' => 'Автоматичне керування обліковими записами негайно припиниться, а всі зіставлення груп буде видалено. Цю дію неможливо скасувати.',
    'provisioning_to_the_downstream_app_stops_immediately_th_6d193c25' => 'Автоматичне керування обліковими записами у цільовому застосунку негайно припиниться. Цю дію неможливо скасувати.',
    'provisioning_to_the_downstream_app_stops_immediately_th_948dd5a5' => 'Автоматичне керування обліковими записами у цільовому застосунку негайно припиниться. Уже створені там користувачі залишаться.',
    'phone_number_removed_their_other_factors_and_recovery_c_a792580f' => 'Номер телефону видалено. Інші фактори автентифікації та коди відновлення користувача залишилися без змін.',
    'people_already_connected_keep_the_scopes_they_agreed_to_f979f289' => 'Уже підключені користувачі збережуть погоджені області доступу до наступного підключення.',
    'origins_updated_the_change_is_live_on_the_next_request_6bb5bfb0' => 'Джерела оновлено. Зміна набуде чинності під час наступного запиту.',
    'other_systems_may_be_using_this_changing_it_changes_the_41e0f485' => 'Інші системи можуть використовувати це значення. Його зміна змінює URL, які вони зберігають.',
    'people_who_rely_on_this_provider_lose_their_way_in_this_10f27c15' => 'Користувачі, які покладаються на цього постачальника, втратять цей спосіб входу. Цю дію неможливо скасувати.',
    'project_suspended_its_environments_stay_live_but_no_new_be6ca1ef' => 'Проєкт призупинено. Його середовища залишаються активними, але нові не можна додавати до повторної активації проєкту.',
    'role_definition_activated_existing_holders_now_use_thes_381596d2' => 'Визначення ролі активовано. Наявні власники ролі тепер використовують ці дозволи.',
    'rule_activated_grants_that_would_break_it_are_blocked_f_fb4adf4c' => 'Правило активовано. Відтепер надання доступу, яке порушило б його, блокується.',
    'schema_saved_events_of_this_action_are_checked_against_8215a899' => 'Схему збережено. Відтепер події цієї дії перевіряються за нею.',
    'schema_saved_every_check_is_decided_by_it_from_now_on_e54cf8c0' => 'Схему збережено. Відтепер вона визначає результат кожної перевірки.',
    'refuse_events_whose_action_has_no_schema_turn_on_once_e_c5af42c9' => 'Відхиляйте події, для дії яких немає схеми. Увімкніть, коли кожна дія, яку надсилає застосунок, матиме схему.',
    'objects_are_written_to_prefix_yyyy_mm_dd_hh_batch_ndjso_5c6035ae' => 'Об’єкти записуються до prefix/yyyy/mm/dd/hh/batch.ndjson.gz, по одній події в рядку.',
    'only_for_an_s3_compatible_store_such_as_minio_or_cloudf_266ca7ae' => 'Лише для сховища, сумісного з S3, наприклад MinIO або Cloudflare R2. Якщо поле порожнє, використовується кінцева точка AWS для регіону.',
    'register_this_as_an_allowed_redirect_uri_at_the_provide_b537b90c' => 'Зареєструйте це в постачальника як дозволений URI перенаправлення, точно в наведеному вигляді.',
    'webhooks_sign_out_notices_to_connected_apps_role_update_776577f9' => 'Вебхуки, сповіщення про вихід для підключених застосунків, оновлення ролей із цих застосунків і листи в черзі обробляються фоновими процесами черги, без очікування користувача. Якщо жоден процес не працює, нічого не надсилається, хоча решта консолі виглядає нормально. На цій сторінці можна побачити проблему.',
    'a_round_where_you_go_through_who_holds_which_role_and_c_617023b9' => 'Перегляд, під час якого ви перевіряєте, хто має яку роль, і підтверджуєте, чи вона ще потрібна. Доступ накопичується непомітно: люди змінюють команди, але зберігають старі дозволи. Перегляд дозволяє прибрати такий доступ. Відкликання застосовуються після закриття перегляду, а весь процес записується для аудитора.',
    'if_the_app_declares_a_different_url_later_this_approval_d8bd0ea4' => 'Якщо застосунок згодом укаже інший URL, це схвалення буде скасовано й запитано знову. Зміна адреси, куди надсилаються паролі, потребує нового схвалення. Делегований вхід — перехідне рішення: коли в старій системі залишиться мало людей, вимкніть його та надішліть цій групі скидання пароля.',
    'lets_your_people_sign_in_with_the_company_account_they_5186cda3' => 'Дозволяє входити з наявним корпоративним обліковим записом, наприклад Microsoft Entra ID, Okta чи Google Workspace, замість окремого пароля тут. Один раз підключіть постачальника ідентифікації та підтвердьте домени електронної пошти. Усіх користувачів цих доменів буде спрямовано до постачальника для входу.',
    'every_person_with_an_identity_in_this_environment_which_f9f26f27' => 'Усі люди з ідентичністю в цьому середовищі незалежно від організацій, до яких належать. Відкрийте людину, щоб скинути пароль або другий фактор, завершити сеанси, вимкнути обліковий запис, змінити організації й ролі або остаточно видалити дані за запитом на реалізацію права на видалення.',
    'paste_the_provider_s_metadata_xml_or_its_metadata_url_a_70d6c8b8' => 'Вставте XML метаданих постачальника або їхню URL-адресу, і поля нижче заповняться автоматично.',
    'paste_this_into_your_identity_provider_with_the_bearer_6f366a6e' => 'Вставте це у свого постачальника ідентифікації разом із bearer-токеном каталогу, який підключаєте.',
    'point_your_oidc_client_at_these_discovery_exposes_every_81f0fa9a' => 'Налаштуйте ці адреси в клієнті OIDC. Механізм виявлення автоматично надає всі кінцеві точки.',
    'register_an_application_that_uses_this_environment_as_i_8eee8cef' => 'Зареєструйте застосунок, який використовує це середовище як постачальника ідентифікації SAML.',
    'register_one_to_let_an_application_sign_its_users_in_wi_e20e6b01' => 'Зареєструйте застосунок, щоб його користувачі могли входити з обліковими записами, які вже мають у цьому середовищі.',
    'only_the_apps_listed_here_get_a_token_everything_else_i_3d600e70' => 'Лише перелічені тут застосунки отримають токен. Усі інші запити відхиляються.',
    'no_entitlements_set_for_this_organization_it_runs_on_th_76313cb5' => 'Для цієї організації не встановлено прав використання. Застосовуються типові налаштування інсталяції.',
    'organizations_in_the_targeted_environment_as_the_manage_2f2361fb' => 'Організації в цільовому середовищі у вигляді дерева керування.',
    'owned_by_this_environment_rather_than_by_an_organizatio_60be3a32' => 'Належить цьому середовищу, а не організації',
    'platform_operators_administer_environments_across_the_w_e0a9f173' => 'Оператори платформи керують середовищами всієї інсталяції.',
    'platform_wide_usage_across_every_environment_not_only_t_0e12a08a' => 'Використання всієї платформи в усіх середовищах, а не лише у вибраному в консолі.',
    'how_organization_owners_and_operators_sign_in_to_cbox_i_444d5c8b' => 'Спосіб входу власників і операторів організацій до Cbox ID налаштовується в консолі середовища платформи.',
    'these_run_in_the_middle_of_an_operation_not_after_it_an_c325ec80' => 'Ці точки розширення виконуються під час операції, а не після неї, і їхня відповідь змінює результат: ваша кінцева точка може додати дані до токена або відмовити у вході. Вони безпосередньо беруть участь у виконанні операції — повільну чи несправну кінцеву точку відчує людина, яка намагається ввійти.',
    'your_identity_provider_creates_updates_and_deactivates_2d9dc172' => 'Постачальник ідентифікації сам створює, оновлює та деактивує тут людей через стандарт SCIM. Прийняття на роботу чи звільнення, зафіксоване в кадровій системі, за секунди доходить до застосунків, без заявок у підтримку й забутих облікових записів — що особливо важливо під час звільнення.',
    'how_many_organizations_users_single_sign_on_connections_8e80258f' => 'Кількість організацій, користувачів, підключень єдиного входу, застосунків і синхронізацій користувачів у цьому середовищі, кожне з посиланням на свою сторінку. Ярлики нижче запускають найпоширеніші дії: створення організації, користувача, підключення єдиного входу або застосунку.',
    'a_role_is_a_job_title_your_apps_understand_editor_suppo_73cd7eac' => 'Роль — це обов’язок, який розуміють ваші застосунки, наприклад «Редактор» або «Працівник підтримки». Тут ви визначаєте, хто має кожну роль, а кожен застосунок сам вирішує, що вона дозволяє. Ролі супроводжують людину в усіх підключених застосунках, тож надавати й відкликати доступ можна в одному місці.',
    'mirrors_every_audit_log_entry_into_your_security_team_s_b980f702' => 'Копіює кожен запис журналу аудиту в інструменти команди безпеки, наприклад SIEM, одразу після записування. Налаштуйте призначення, щоб розслідування починалися у вже використовуваних інструментах без запиту на експорт. Доставка відбувається щонайменше один раз, тому іноді можливі дублікати.',
    'an_organization_appears_here_the_moment_somebody_signs__d46ff7af' => 'Робочий простір з’явиться тут, щойно хтось зареєструється. Також можна створити його кнопкою Новий робочий простір вище.',
    'add_the_domain_this_organization_s_people_have_email_ad_e68cad70' => 'Додайте домен електронних адрес людей у цій організації, опублікуйте TXT-запис і підтвердьте домен.',
    'prove_ownership_of_an_email_domain_to_route_your_team_t_bc84ec01' => 'Підтвердьте право власності на поштовий домен, щоб автоматично спрямовувати команду до SSO.',
    'prove_the_organization_owns_a_domain_then_route_everyon_3c9f7db4' => 'Підтвердьте, що організація володіє доменом, а потім спрямовуйте всіх його користувачів до входу організації.',
    'sandbox_environments_send_no_email_copy_the_setup_link_e5709a6a' => 'Тестові середовища не надсилають електронних листів. Скопіюйте посилання для налаштування нижче та поділіться ним самостійно.',
    'it_replaces_the_sealed_value_on_rotate_and_is_never_sho_cec701f1' => 'Під час ротації замінює зашифроване значення й більше не показується. Збережіть власну копію, якщо вона потрібна.',
    'replace_the_sealed_value_with_a_new_credential_the_stor_17b46d38' => 'Замініть зашифроване значення новими обліковими даними. Збережене значення ніколи не показується.',
    'sealed_the_moment_you_save_it_and_never_shown_again_kee_db995569' => 'Шифрується під час збереження й більше не показується. Збережіть власну копію, якщо вона потрібна.',
    'stored_sealed_and_never_shown_again_leave_it_empty_to_k_72338e4f' => 'Зберігається зашифрованим і більше не показується. Залиште порожнім, щоб зберегти поточне значення.',
    'secret_rotated_and_the_previous_one_has_stopped_working_14aacb17' => 'Секрет замінено, а попередній більше не працює. Скопіюйте новий зараз — його більше не буде показано.',
    'revoking_is_immediate_and_permanent_no_future_lease_can_27e17e18' => 'Відкликання діє негайно й назавжди. Жоден майбутній тимчасовий дозвіл доступу не зможе відкрити цей секрет.',
    'metadata_schemas_are_a_subset_of_json_schema_an_object_64eba270' => 'Схеми метаданих — це підмножина JSON Schema: об’єкт, властивості якого мають тип рядка, числа, цілого числа, логічного значення або null, з переліками дозволених значень та обмеженнями довжини, діапазону, шаблону й формату. Збереження зміни створює нову версію; вже записані події зберігають версію, за якою їх перевіряли.',
    'each_pipe_lets_people_connect_their_own_account_at_a_se_ec4853ae' => 'Кожне з’єднання дозволяє людям підключити власний обліковий запис у сервісі на кшталт GitHub, Google чи Slack. Їхні токени зберігаються тут у зашифрованому вигляді й оновлюються. Уповноважені застосунки запитують чинний токен щоразу, коли звертаються до сервісу від імені людини, і самі його не зберігають.',
    'an_admin_support_role_is_a_role_you_grant_to_your_own_p_4b6ac4cb' => 'Роль адміністрування й підтримки надається власним працівникам, наприклад командам підтримки або експлуатації, у всьому середовищі. Вона діє в кожній організації, а адміністратори організацій не можуть її побачити, надати чи вилучити. Власна роль застосунку, надана таким чином, діє лише в цьому застосунку.',
    'an_environment_is_a_fully_isolated_identity_service_wit_993d6053' => 'Середовище — це повністю ізольований сервіс ідентифікації з власними користувачами, ключами, входом і видавцем. Тут наведено всі середовища цього встановлення разом з організаціями, яким вони належать. Створіть середовище, виберіть його в консолі й додайте першу організацію та адміністратора.',
    'pick_the_app_and_tick_only_what_the_key_needs_you_can_c_69b0060d' => 'Виберіть застосунок і позначте лише те, що потрібно ключу. Можна створити скільки завгодно ключів, по одному для кожної інтеграції.',
    'scopes_saved_they_apply_from_the_next_token_this_app_as_db2304fa' => 'Області доступу збережено. Вони діятимуть починаючи з наступного токена, який запитає цей застосунок.',
    'self_service_sign_up_is_on_people_can_create_an_account_af9f74f0' => 'Самостійна реєстрація ввімкнена. Користувачі можуть створювати облікові записи та власні організації.',
    'start_from_a_preset_then_adjust_each_scope_is_marked_wi_60006824' => 'Почніть із готового набору й налаштуйте його. Для кожної області доступу вказано найшкідливішу дію, яку вона дозволяє.',
    'the_application_can_no_longer_sign_users_in_through_thi_72052d67' => 'Застосунок більше не зможе виконувати вхід користувачів через це середовище. Цю дію неможливо скасувати.',
    'add_one_below_to_offer_it_on_this_organization_s_page_51427e0a' => 'Додайте його нижче, щоб запропонувати на сторінці цієї організації.',
