    'the_identifier_the_application_calls_itself_in_its_auth_afe05ddf' => 'Ідентифікатор, яким застосунок позначає себе у своїх AuthnRequests.',
    'a_phone_with_the_authenticator_app_installed_becomes_th_caef4b54' => 'Телефон зі встановленим застосунком автентифікації дозволяє відповідати на запити схвалення й сповіщає, коли хтось входить у ваш обліковий запис. Зареєструйте його один раз, відсканувавши код. Якщо втратите телефон, негайно вилучіть його тут, щоб він більше нічого не міг схвалювати.',
    'an_organization_is_one_signed_up_company_s_home_on_this_b98406a0' => 'Робочий простір — це місце однієї зареєстрованої компанії в цьому встановленні, яке містить її проєкти, середовища й команду. Відкрийте його для перегляду продуктів і середовищ або призупиніть: це завершить сеанси учасників і зупинить вхід у всіх його середовищах.',
    'when_an_app_or_an_ai_agent_needs_your_go_ahead_to_act_a_51a99858' => 'Коли застосунку чи AI-агенту потрібна ваша згода на дії від вашого імені, він не завжди може запитати її на екрані перед вами — тому запитує тут. Схвалюйте лише запити, які ви самі розпочали, і перевіряйте, чи збігається показаний код із кодом на пристрої, що надіслав запит.',
    'a_project_is_one_of_your_products_with_its_own_plan_sig_45d566d1' => 'Проєкт — це один із ваших продуктів із власним тарифом, входом і середовищами, наприклад робочим та передпродукційним. Відкрийте середовище звідси для адміністрування. Створюйте новий проєкт, коли запускаєте продукт, який має працювати й оплачуватися окремо.',
    'send_this_endpoint_every_organization_s_events_in_this_ea696387' => 'Надсилайте до цієї кінцевої точки події всіх організацій цього середовища, а не лише однієї.',
    'signature_scheme_changed_deliveries_are_signed_the_new_9a0fb26a' => 'Схему підписування змінено. Починаючи з наступної спроби надсилання підписуватимуться новим способом.',
    'the_hook_stops_being_called_and_its_signing_secret_is_d_ad833a77' => 'Hook більше не викликатиметься, а його секрет підписування буде знищено. Цю дію неможливо скасувати.',
    'the_bucket_in_the_path_rather_than_the_host_name_a_cust_070b78d0' => 'Бакет міститься в шляху, а не в імені хоста. Власна кінцева точка вже використовує цей формат.',
    'every_app_that_signs_people_in_through_cbox_id_or_calls_1e151c65' => 'Кожен застосунок, що забезпечує вхід через Cbox ID або викликає його API, реєструється тут і отримує власні облікові дані. Створюйте окрему реєстрацію для кожного застосунку й середовища. Ніколи не використовуйте спільні облікові дані, щоб можна було відкликати їх для одного застосунку, не зупиняючи інші.',
    'looks_up_an_organization_by_name_or_handle_or_a_user_by_d7460886' => 'Шукає організацію за назвою чи ідентифікатором або користувача за іменем чи електронною адресою в усіх середовищах цього встановлення, а не лише у вибраному в консолі. Використовуйте, коли хтось просить допомоги, а ви не знаєте, у якому середовищі він перебуває.',
    'see_an_app_exactly_as_one_of_its_users_does_you_sign_in_8eafae42' => 'Побачте застосунок так, як його бачить один із користувачів: увійдіть від його імені, указавши причину, щонайбільше на годину. Застосунок дізнається, хто насправді ним користується, і не отримує можливості продовжувати сеанс. Журнал аудиту організації записує, хто це зробив і чому.',
    'a_project_is_one_idp_product_this_organization_owns_and_d87379c8' => 'Проєкт — це один продукт IdP, що належить цій організації й об’єднує середовища. Доки організація не створить проєкт у власній консолі, тут немає середовища для вибору чи відкриття. Цей екран не дозволяє створити проєкт від імені організації.',
    'sign_in_with_face_id_touch_id_windows_hello__97a33786' => 'Входьте за допомогою Face ID, Touch ID, Windows Hello або ключа безпеки — без пароля.',
    'sign_ins_and_changes_to_your_password_passkeys_and_two_9e7da5c8' => 'Тут відображаються входи та зміни пароля, ключів доступу й налаштувань двофакторної автентифікації.',
    'text_message_codes_are_no_longer_offered_her_1a9ddf89' => 'Коди через SMS тут більше недоступні. Використайте застосунок автентифікації або ключ доступу.',
    'that_device_stops_being_able_to_sign_you_in__5e148d22' => 'Цей пристрій більше не зможе виконувати ваш вхід. Його можна знову додати на цій сторінці.',
    'that_request_is_no_longer_waiting_it_was_answered_used_80728be7' => 'Цей запит більше не очікує — на нього відповіли, його використали або строк його дії минув.',
    'the_agent_is_told_no_when_it_asks_again_and_has_to_star_c28d8870' => 'Під час наступного запиту агент отримає відмову й муситиме почати спочатку. Відмова записується до журналу аудиту.',
    'the_browser_tab_icon_on_your_sign_in_pages_a_square_png_04f6f405' => 'Піктограма вкладки браузера на сторінках входу. Квадратне зображення PNG, ICO або WebP розміром до 256 KB.',
    'the_hosted_sign_in_s_look_logo_and_favicon_and_the_name_39304e21' => 'Вигляд, логотип і favicon розміщеної сторінки входу, а також ім’я та відправник, яких бачать користувачі.',
    'sent_when_someone_s_account_is_created_leave_it_empty_f_c7c58d7f' => 'Надсилається під час створення облікового запису. Залиште порожнім для типового значення.',
    'only_for_a_provider_that_does_not_publish_its_signing_k_e4c5eb2d' => 'Лише для постачальника, який не публікує ключі підпису (jwks_uri) у документі виявлення. Інакше ключі зчитуються звідти, зокрема після ротації. Введіть відкритий ключ PEM. Він зберігається зашифрованим і більше не показується; залиште порожнім, щоб зберегти поточний.',
    'some_pairs_of_roles_must_never_sit_with_the_same_person_70e4454a' => 'Деякі пари ролей ніколи не повинні належати одній людині: той, хто ініціює платіж, не має його також схвалювати. Вкажіть ці пари тут. Cbox ID блокує нові призначення, які порушили б правило, і показує, хто вже має конфліктну пару ролей.',
    'api_keys_and_tokens_your_apps_and_agents_need_for_other_f9b71876' => 'Ключі API й токени, потрібні застосункам і агентам для інших сервісів, зберігаються тут зашифрованими, а не в конфігурації кожного застосунку. Ви вводите секрет один раз і дозволяєте певним застосункам його використовувати. Він більше не показується; якщо втратите його, замініть новим.',
    'serves_an_environment_s_identity_endpoints_on_a_domain_f6582d38' => 'Надає кінцеві точки ідентифікації середовища на вашому домені, наприклад login.example.com, замість нашого. Володіння доменом підтверджується записом DNS TXT. Налаштуйте його, якщо під час входу люди повинні бачити лише вашу адресу.',
    'the_name_of_your_organization_which_your_projects_envir_fde906b5' => 'Назва організації, яка об’єднує проєкти, середовища й команду та відображається в усій консолі. Видалення організації вимикає всі середовища, через які люди входять. Тому видалення замовляють через підтримку, а не запускають кнопкою.',
    'the_claim_is_dropped_if_capture_was_on_people_on_this_d_17d5c40e' => 'Заявку на право власності на домен буде видалено. Якщо обов’язковий SSO було ввімкнено, користувачі цього домену повернуться до звичайного входу.',
    'this_domain_will_no_longer_route_its_users_through_this_281a9227' => 'Цей домен більше не спрямовуватиме користувачів через SSO цієї організації. Цю дію неможливо скасувати.',
    'this_client_can_no_longer_lease_the_secret_any_lease_it_c5728383' => 'Цей клієнт більше не може отримувати тимчасовий доступ до секрету. Уже надані тимчасові дозволи залишаються чинними до завершення строку дії.',
    'this_endpoint_stops_receiving_events_and_its_delivery_h_b6a65cf3' => 'Ця кінцева точка припинить отримувати події, а історію надсилань буде видалено. Цю дію неможливо скасувати.',
    'whatever_the_holder_has_wired_this_key_into_stops_worki_789a1199' => 'Усе, де власник використовує цей ключ, негайно припинить працювати. Цю дію неможливо скасувати.',
    'the_name_of_the_organization_these_identity_providers_a_72767cbb' => 'Назва організації, у межах якої виставляються рахунки за цих постачальників ідентифікації та здійснюється керування ними.',
    'the_plan_allowance_on_their_first_product_billing_hangs_f5035935' => 'Ліміти тарифного плану першого продукту. Оплата прив’язана до продукту, а не до організації.',
    'this_project_has_no_environments_yet_nothing_under_it_s_a2247eb5' => 'У цьому проєкті ще немає середовищ. Жодна його частина не надає послуг автентифікації.',
    'this_project_has_used_every_environment_its_plan_allows_b891ec0b' => 'Цей проєкт використав усі середовища, дозволені тарифним планом. Перейдіть на вищий план, щоб додати більше.',
