    'local_or_reserved_address_1bfdaa4f' => 'Локальна або зарезервована адреса',
    'each_organization_is_a_company_or_team_using_your_produ_08cdcb7d' => 'Кожна організація — це компанія чи команда, що використовує ваш продукт, із власними учасниками, ролями, доменами та єдиним входом. Створіть по одній для кожної зареєстрованої компанії. Відкрийте її для керування учасниками, запрошеннями й підтвердженими доменами або для призупинення.',
    'cbox_id_posts_a_signed_message_to_your_endpoint_after_s_8dadac57' => 'Cbox ID надсилає підписане повідомлення на вашу кінцеву точку після події, наприклад приєднання учасника чи зміни ролі, щоб системи могли реагувати без періодичного опитування. Невдала доставка повторюється. Подія вже сталася: кінцеву точку повідомляють, але вона не визначає результат.',
    'a_schema_says_what_an_action_s_events_must_look_like_wh_d27be344' => 'Схема визначає структуру подій дії: які типи цільових об’єктів вони вказують і що містять їхні метадані. Події дії зі схемою перевіряються під час отримання. Без схеми їх приймають у надісланому вигляді, якщо не ввімкнено суворий режим.',
    'everyone_who_administers_this_organization_the_built_in_69802df4' => 'Усі адміністратори цієї організації, їхні вбудовані ролі — Власник, Адміністратор, Розробник, Учасник або Переглядач — і доступні їм середовища. Запрошуйте людей електронною поштою й надавайте кожному лише середовища, потрібні для роботи.',
    'let_the_people_who_use_your_apps_connect_their_own_gith_19a2d0ed' => 'Дозвольте користувачам застосунків підключати власні облікові записи GitHub, Google, Slack або Salesforce, щоб застосунки могли викликати ці API від їхнього імені. Токени зберігаються тут зашифрованими й оновлюються, а тимчасовий доступ до них отримують лише уповноважені застосунки.',
    'the_invitee_accepts_by_email_nobody_is_added_to_an_orga_04408aaf' => 'Запрошена особа приймає запрошення електронною поштою. Нікого не додають до організації без згоди.',
    'this_user_has_no_signed_in_sessions_right_now_they_appe_0ac73d09' => 'Цей користувач зараз не має активних сеансів. Вони з’являться тут після його входу.',
    'this_user_is_held_at_a_password_change_they_cannot_reac_ce196382' => 'Цей користувач має змінити пароль. Він не отримає доступу ні до чого, доки не замінить виданий вами пароль.',
    'user_created_they_have_no_way_to_sign_in_until_you_send_a612f0b1' => 'Користувача створено. Він не зможе ввійти, доки ви не надішлете йому посилання.',
    'user_erased_their_account_is_pseudonymised_and_the_eras_51e1f69a' => 'Дані користувача видалено. Обліковий запис псевдонімізовано, а видалення записано в журналі аудиту як user.erased.',
    'platform_operators_administer_every_organization_and_en_36866fb1' => 'Оператори платформи адмініструють усі організації й середовища цього встановлення на рівні вище кожної з них. Додавайте оператора лише для людини, яка обслуговує саме встановлення, і призупиняйте її доступ, щойно це перестає бути її обов’язком.',
    'every_organization_in_the_environment_the_console_is_po_0de4eff9' => 'Усі організації в середовищі, вибраному в консолі, у вигляді дерева реселерів, керованих ними організацій та їхніх підрозділів. Тут можна створити чи призупинити організацію або перемістити її під іншу батьківську організацію.',
    'sign_ins_tokens_issued_new_users_and_two_factor_enrolme_e9040ee7' => 'Входи, видані токени, нові користувачі й реєстрації двофакторної автентифікації за днями протягом останніх 30 днів, якщо встановлення не задає інший період. Сторінка залишається порожньою, доки оператор не налаштує зберігання аналітичних даних.',
    'set_this_as_the_role_s_trust_policy_iam_roles_trust_rel_d432cbe5' => 'Установіть це як політику довіри ролі (IAM › Roles › Trust relationships). Платформа може прийняти роль лише після надання зовнішнього ID цього потоку, тож ніхто інший на платформі не зможе спрямувати потік до вашої ролі.',
    'their_it_contact_left_blank_you_copy_the_lin_2fe54822' => 'Їхній контакт з ІТ. Якщо залишити поле порожнім, посилання потрібно скопіювати самостійно.',
    'presets_colours_corners_type_edited_with_a_live_preview_ff61e898' => 'Готові стилі, кольори, кути й типографіка — з попереднім переглядом змін у реальному часі.',
    'where_a_copy_of_every_audit_entry_is_delivered_as_it_is_c6b9e401' => 'Куди надсилається копія кожного запису аудиту одразу після створення.',
    'where_sign_ins_go_for_people_who_have_not_moved_to_cbox_be5f68b3' => 'Куди спрямовуються входи користувачів, які ще не перейшли на Cbox ID.',
    'where_the_provider_posts_its_assertion_give_this_to_who_5b098f34' => 'Куди постачальник надсилає своє твердження. Передайте цю адресу тому, хто налаштовує IdP.',
    'where_the_signed_assertion_is_posted_back_must_be_https_2dc6e396' => 'Куди надсилається підписане твердження у відповідь. Має використовувати https.',
    'where_we_exchange_the_client_credentials_for_a_short_li_2afa7c75' => 'Де перед кожним пакетом ми обмінюємо облікові дані клієнта на короткочасний токен.',
    'who_connected_an_account_through_this_pipe_tokens_are_n_ea456475' => 'Хто підключив обліковий запис через це з’єднання. Токени ніколи не показуються.',
    'this_connection_belongs_to_the_environment_itself_it_si_543963d3' => 'Це підключення належить самому середовищу. Воно виконує вхід користувачів, але не додає їх до жодної організації.',
    'this_organization_s_entries_and_nothing_from_any_other_1ab06e62' => 'Записи цієї організації, без жодних записів інших організацій.',
    'what_you_create_here_belongs_to_this_organization_and_t_fc8e15c4' => 'Усе, що ви створюєте тут, належить лише цій організації.',
    'whose_people_are_pushed_or_tick_the_box_above_to_send_e_bb15010f' => 'Користувачів якої організації надсилати — або позначте поле вище, щоб надсилати всі організації.',
    'whose_people_sign_in_through_it_its_domains_and_admin_p_9c461a3e' => 'Користувачі якої організації входять через це підключення. Її домени та посилання на портал адміністратора розміщені на сторінці організації.',
    'every_browser_and_device_signed_in_as_you_the_apps_you_ee516093' => 'Усі браузери й пристрої, що ввійшли у ваш обліковий запис, застосунки з дозволом діяти від вашого імені, а також недавні входи й зміни безпеки. Якщо не впізнаєте якусь активність, завершіть сеанс або відкличте доступ застосунку, а потім змініть пароль.',
    'every_change_made_in_this_organization_who_did_what_to_1d80a907' => 'Кожна зміна в цій організації: хто що зробив, з яким об’єктом і коли. Записи з’єднані ланцюжком хешів, тому видалення чи редагування запису порушує ланцюжок і стає помітним. Навмисно лише для читання — це журнал, який ви надаєте аудитору.',
    'leave_it_empty_for_almost_every_provider_its_id_tokens_e39d64b9' => 'Для майже всіх постачальників залиште порожнім: ID-токени перевіряються ключами підпису, опублікованими в документі виявлення (jwks_uri), зокрема після ротації. Вставляйте відкритий ключ PEM постачальника лише тоді, коли він не публікує жодного.',
    'sign_ins_and_requests_that_cbox_id_scored_as_risky_enou_b09e917e' => 'Входи й запити, які Cbox ID оцінив як достатньо ризиковані для позначення, від найновіших, з оцінкою та її причинами. Перегляньте після зростання кількості невдалих входів або коли хтось повідомляє про вхід, якого не здійснював.',
    'this_environment_serves_an_mcp_server_next_to_its_rest_8094252a' => 'Це середовище надає MCP-сервер поряд із REST API. Підключіть агента з ключем керування, і він зможе виконувати лише те, що дозволяють області доступу ключа, з тими самими перевірками, схваленнями й журналом аудиту, що й консоль.',
    'nothing_recorded_matches_these_filters_widen_the_range_804705cd' => 'Немає записів, що відповідають цим фільтрам. Розширте діапазон або приберіть фільтр.',
    'searches_organizations_and_users_across_every_environme_031a8626' => 'Шукає організації та користувачів у всіх середовищах цієї інсталяції.',
    'the_ten_organizations_with_the_most_members_and_the_env_1c7ea5a5' => 'Десять організацій із найбільшою кількістю учасників і середовище, до якого належить кожна',
    'who_is_signed_in_as_them_right_now_why_a_sign_in_was_al_181f0520' => 'Хто зараз увійшов як цей користувач. Radar показує, чому вхід дозволено, спрямовано на додаткову перевірку або заблоковано.',
    'what_this_organization_s_sign_in_is_wired_to_read_from_cde71601' => 'З чим пов’язаний вхід цієї організації відповідно до фактичних налаштувань.',
    'an_organization_s_own_provider_replaces_the_environment_5a3f34fa' => 'Власний постачальник організації замінює постачальника середовища на її сторінці входу. Також показано організації, які вимкнули постачальника середовища. Це лише прибирає кнопку зі сторінки; доступ цим методом блокує саме вимога SSO.',
    'apps_that_keep_their_own_user_list_drift_out_of_step_th_fc8e8671' => 'Застосунки з власним списком користувачів утрачають узгодженість, щойно хтось приєднується чи йде. Підключення SCIM передає їм кожну зміну, коли вона відбувається, включно зі звільненнями, про які найпростіше забути.',
    'point_an_identity_provider_at_our_scim_endpoint_connect_9f06ef10' => 'Спрямуйте постачальника ідентифікації на нашу кінцеву точку SCIM, підключіть Google Workspace чи Microsoft Entra або кадрову систему — Workday, BambooHR, Rippling, HiBob чи Personio. Ми отримуватимемо дані людей за розкладом.',
    'the_audit_trail_lives_here_and_your_security_team_s_too_621820fa' => 'Журнал аудиту тут, а інструменти команди безпеки — в іншому місці. Потік копіює кожен запис до них одразу після записування, щоб розслідування не починалося із запиту на експорт CSV.',
    'the_authorization_and_token_endpoints_are_discovered_fr_f26237b1' => 'Кінцеві точки авторизації та токенів визначаються за видавцем, тому більше нічого вставляти не потрібно.',
    'the_services_id_you_enabled_sign_in_with_apple_on_not_t_c93a711d' => 'Services ID, для якого ввімкнено Sign in with Apple, а не App ID.',
    'the_signing_secret_is_shown_once_right_after_you_create_aa1c7a87' => 'Секрет підписування показується лише раз, одразу після створення кінцевої точки.',
    'the_signing_secret_is_shown_once_right_after_you_regist_35bf6d24' => 'Секрет підписування показується лише раз, одразу після реєстрації кінцевої точки.',
    'who_issued_it_the_name_you_would_search_for_in_their_da_22a5c245' => 'Хто його видав — назва, яку ви шукали б на панелі постачальника.',
    'verify_that_authnrequests_really_come_from_this_applica_f3c58c70' => 'Перевіряйте, чи AuthnRequests справді надходять від цього застосунку, за допомогою його власного сертифіката підписування.',
    'this_is_exactly_how_your_sign_in_renders_the_preview_sh_a4878600' => 'Саме так відображається ваша сторінка входу. Попередній перегляд використовує той самий механізм тем, що й робоча сторінка.',
    'this_is_your_environment_s_default_sign_in_an_organizat_d17d58dd' => 'Це типова сторінка входу вашого середовища. Організація може перевизначити її власною темою.',
    'this_overrides_your_environment_s_default_for_your_orga_41bfb686' => 'Перевизначає типове налаштування середовища для входу вашої організації.',
    'what_your_people_see_in_place_of_cbox_id_and_who_your_m_32cb946d' => 'Що користувачі бачать замість Cbox ID та хто вказаний відправником ваших листів.',
    'your_branding_changes_have_not_been_saved_leave_this_pa_1a8dbb2f' => 'Зміни фірмового оформлення не збережено. Якщо ви залишите цю сторінку, вони будуть втрачені.',
    'organization_suspended_its_members_can_no_longer_sign_i_35d8877a' => 'Робочий простір призупинено. Його учасники більше не можуть входити, а середовища припиняють надавати автентифікацію.',
    'a_downstream_api_key_your_apps_and_agents_present_to_a_069a6a5e' => 'Ключ API зовнішнього сервісу, який застосунки й агенти надають постачальнику. Зберігається зашифрованим і передається лише явно уповноваженим клієнтам.',
    'a_list_of_the_target_types_this_action_may_name_each_wi_26513896' => 'Список типів цільових об’єктів, які ця дія може вказувати, кожен із необов’язковою схемою метаданих. Залиште порожнім, щоб дозволити всі типи.',
    'a_separate_identity_provider_product_with_its_own_envir_97a4c57b' => 'Окремий продукт постачальника ідентифікації з власними середовищами й тарифом, який оплачується незалежно від інших проєктів.',
    'add_an_endpoint_and_your_own_systems_hear_about_members_263677b5' => 'Додайте кінцеву точку, щоб системи одразу дізнавалися про нових учасників, зміни ролей і невдалі входи, без періодичного опитування та нічних експортів.',
    'an_environment_is_fully_isolated_its_own_users_keys_sig_bc49f6f9' => 'Середовище повністю ізольоване, з власними користувачами, ключами, входом і видавцем. Створіть перше вище, а потім додайте організацію й адміністратора.',
    'applications_you_approve_a_command_line_a_device_anothe_9ae677c4' => 'Тут з’являються схвалені вами застосунки — інструмент командного рядка, пристрій або інший продукт, що забезпечує вхід через Cbox ID. Доступ будь-якого з них можна відкликати.',
    'as_an_administrator_set_up_an_authenticator__17d31053' => 'Як адміністратор спочатку налаштуйте застосунок автентифікації або ключ доступу. Потім можна додати номер телефону як резервний метод.',
    'attempts_this_rule_decided_are_decided_by_the_next_matc_ebfc6722' => 'Починаючи з наступної спроби, випадки, які вирішувало це правило, оцінюватиме наступне відповідне правило або вбудовані правила.',
    'called_synchronously_while_somebody_waits_at_the_sign_i_cf697019' => 'Викликається синхронно, поки людина чекає на екрані входу. Перевіряйте заголовок X-Cbox-Signature у кожному запиті.',
    'change_where_this_stream_delivers_or_the_credential_it_e8fc2e8f' => 'Змініть призначення потоку або використовувані облікові дані. Збереження повторно перевіряє налаштування й повторює доставку під час наступного запуску.',
    'withdrawn_people_already_migrated_are_unaffected_anyone_228f7b22' => 'Відкликано. Уже перенесених користувачів це не зачіпає; ті, хто залишився в старій системі, не можуть увійти.',
    'your_administrator_has_turned_off_two_factor_e8143f3a' => 'Адміністратор вимкнув двофакторну автентифікацію для цього середовища.',
    'your_existing_codes_stop_working_immediately_c2dbcb02' => 'Наявні коди негайно припинять працювати. Нові показуються лише раз.',
    'your_profile_how_you_sign_in_and_the_session_ab7a0592' => 'Ваш профіль, способи входу та сеанси, у яких зараз виконано вхід із вашим обліковим записом.',
    'you_sign_in_to_the_provider_and_it_is_linked_59410359' => 'Ви входите в постачальника, і після повернення обліковий запис пов’язується з вами.',
    'this_app_signs_assertions_with_its_own_keys_and_has_no_7e457dd4' => 'Цей застосунок підписує твердження власними ключами й не має секрету клієнта. Натомість замініть ключ у його JWKS.',
    'it_decides_the_kind_of_app_and_its_localhost_redirect_t_0f18e4ab' => 'Визначає тип застосунку та його перенаправлення на localhost із портом, який використовує сервер розробки вашого фреймворку.',
    'serve_an_environment_s_identity_endpoints_on_your_own_d_c475397f' => 'Надавайте кінцеві точки ідентифікації середовища на власному домені, підтвердженому через DNS.',
    'vs_code_asks_for_the_key_the_first_time_and_keeps_it_in_e11c90d5' => 'VS Code запитує ключ під час першого використання та зберігає його у власному сховищі секретів.',
    'we_couldn_t_find_the_txt_record_yet_dns_can_take_a_few_0f4e9bce' => 'Ми ще не знайшли TXT-запис. Оновлення DNS може тривати кілька хвилин.',
    'x_cbox_signature_with_a_hex_hmac_the_default_verified_w_3bc267fa' => 'X-Cbox-Signature із шістнадцятковим HMAC — типовий варіант, який перевіряється за допомогою Cbox SDK.',
    'you_ll_add_its_environments_production_staging_sandbox_d74d2d40' => 'Далі ви додасте виробниче, передвиробниче й тестове середовища.',
    'seen_among_the_newest_events_each_is_accepted_as_sent_u_1b4df3ab' => 'Виявлені серед найновіших подій. Події кожної дії приймаються в надісланому вигляді, доки дія не матиме схеми.',
    'the_moment_your_endpoint_is_called_and_what_its_answer_209c828e' => 'Коли викликається ваша кінцева точка та що дозволено змінювати її відповіді.',
    'use_your_own_the_answer_says_whether_an_account_exists_7e30353b' => 'Використайте власну адресу. Відповідь покаже, чи існує обліковий запис у старій системі.',
    'whatever_their_risk_for_example_the_one_action_you_want_af03fab8' => 'Незалежно від ризику — наприклад, для певної дії, яку ви хочете контролювати.',
    'whatever_your_team_calls_this_provider_it_appears_on_th_aa44d5b2' => 'Назва, яку ваша команда використовує для цього постачальника. Відображається в списку та журналі аудиту.',
    'matches_organization_name_slug_and_user_email_name_case_1c34d2a1' => 'Шукає за назвою чи slug організації та електронною адресою чи ім’ям користувача. Регістр не враховується; % і _ є звичайними символами, а не шаблонами.',
    'add_the_domain_and_publish_the_txt_record_it_shows_or_s_ddb14174' => 'Додайте домен і опублікуйте показаний TXT-запис або надішліть ІТ-адміністратору організації посилання на Портал адміністратора, щоб він це зробив.',
    'add_the_people_who_will_administer_this_organization_wi_75edc5a6' => 'Додайте людей, які адмініструватимуть цю організацію разом із вами. Вони самі налаштують вхід, тож вам не доведеться працювати з їхніми паролями.',
    'agent_preset_full_admin_description' => 'Усі області доступу. Критичні дії з ключами, секретами й входом чекають на ваше підтвердження.',
    'agent_preset_support_description' => 'Читає все й допомагає людям: керує користувачами, членством і запрошеннями. Руйнівні дії чекають на ваше підтвердження.',
    'an_app_signs_people_in_only_to_the_urls_it_lists_charac_a7f88d2a' => 'Застосунок спрямовує користувачів після входу лише на вказані в ньому URL-адреси, що збігаються символ у символ. Позначається, щойно така адреса з’явиться в одному з ваших застосунків.',
    'an_iam_user_allowed_only_s3_putobject_on_the_bucket_its_5337441e' => 'Користувач IAM, якому дозволено лише s3:PutObject у цьому бакеті. Його секретний ключ доступу зберігається зашифрованим.',
    'attach_this_to_the_role_it_may_write_objects_under_the_3d2c7384' => 'Прикріпіть це до ролі: їй буде дозволено лише записувати об’єкти під цим префіксом — без читання, перегляду списку чи видалення.',
    'challenge_a_second_factor_on_sign_in_a_captcha_or_email_38e590f3' => 'Додаткова перевірка — другий фактор під час входу, CAPTCHA або код електронною поштою під час реєстрації',
    'choose_one_under_add_a_provider_it_is_offered_on_every_fe325acd' => 'Виберіть постачальника в розділі «Додати постачальника». Він буде доступний на всіх сторінках входу, якщо ви не обмежите його лише цією організацією.',
    'choose_one_under_add_a_provider_to_offer_it_on_every_si_b0f45965' => 'Виберіть постачальника в розділі «Додати постачальника», щоб він був доступний на всіх сторінках входу.',
    'commit_this_file_and_give_each_person_their_own_key_in_f23e11a2' => 'Додайте цей файл до системи контролю версій і надайте кожній людині власний ключ у змінній середовища. Сам файл не містить секретів.',
    'connect_entra_id_okta_or_google_workspace_and_your_peop_688a5abf' => 'Підключіть Entra ID, Okta або Google Workspace, і ваші користувачі зможуть входити з наявним корпоративним обліковим записом.',
    'every_change_made_here_who_did_what_to_what_and_when_ha_4f61494d' => 'Кожна внесена тут зміна: хто, що, над чим і коли зробив. Записи пов’язані ланцюжком хешів, тому видалення запису буде помітним.',
    'every_environment_on_this_install_and_who_owns_it_creat_78b48199' => 'Усі середовища цього встановлення та їхні власники. Створіть середовище, виберіть його в консолі й додайте першого адміністратора.',
    'every_other_browser_and_device_holding_a_session_as_you_3d2d96e0' => 'Усі інші браузери й пристрої з вашим сеансом утратять доступ під час наступного запиту. Цей сеанс залишиться активним.',
    'everyone_in_it_loses_access_immediately_and_it_disappea_6b76018d' => 'Усі люди негайно втрачають доступ, а організація зникає з усіх списків. Записи зберігаються для аудиту.',
    'everything_on_this_page_is_also_a_rest_endpoint_an_mcp_28d51f03' => 'Усе на цій сторінці також доступне як кінцева точка REST, інструмент MCP і команда CLI, з тими самими правилами й журналом аудиту.',
    'fail_open_or_closed_deliberately_decide_now_what_should_daf1e068' => 'Свідомо виберіть дозвіл або відмову в разі збою: заздалегідь визначте, що має відбуватися, коли ваша кінцева точка недоступна.',
    'failed_sign_ins_on_one_address_within_an_hour_from_anyw_cdda8940' => 'Невдалі входи на одну електронну адресу протягом години з будь-яких джерел — виявляє підбір пароля, розподілений між багатьма IP-адресами.',
    'for_a_pull_directory_paste_its_credentials_and_we_verif_581eae82' => 'Для каталогу з отриманням даних вставте облікові дані. Ми перевіримо їх, перш ніж щось зберігати.',
    'for_one_of_this_environment_s_own_people_an_organizatio_1c327ded' => 'Для людини із цього середовища, яка адмініструє організацію. Агент діє від її імені, у її організації.',
