    'grant_the_specific_apps_that_may_use_it_nothing_else_ca_7554df68' => 'Надайте доступ лише конкретним застосункам, які можуть це використовувати. Жоден інший застосунок не зможе це прочитати.',
    'how_your_organization_s_own_team_signs_in_to_cbox_id_no_11ea0db7' => 'Як власна команда вашої організації входить до Cbox ID. Вхід до ваших застосунків налаштовується окремо в консолі кожного середовища.',
    'image_uploads_are_not_available_on_this_install_the_whi_e33690d3' => 'Завантаження зображень недоступне в цій інсталяції: модуль власного брендування, який їх зберігає, не ввімкнено.',
