    'it_disappears_from_every_list_and_its_people_are_refuse_49a9035c' => 'Організація зникає з усіх списків, а її люди втрачають доступ усюди, як і під час призупинення. Записи зберігаються.',
    'it_is_sealed_on_save_and_never_displayed_again_not_here_e9ace615' => 'Під час збереження шифрується й більше ніколи не показується: ні тут, ні на сторінці секрету, ні після ротації.',
    'keep_them_signed_in_with_refresh_tokens_so_they_need_no_2c9e48d2' => 'Зберігайте їхні сеанси за допомогою токенів оновлення, щоб їм не доводилося входити знову.',
