    'left_empty_a_signing_key_is_generated_for_you_and_shown_7cc3e0ba' => 'Якщо залишити порожнім, буде створено ключ підпису й показано лише один раз. Він зберігається зашифрованим, і отримати його знову неможливо.',
    'let_this_app_call_the_decision_endpoint_for_a_person_s_1b1d78dd' => 'Дозволити цьому застосунку викликати кінцеву точку рішень щодо дозволів і прав користувача в організації.',
