    'let_your_provider_create_and_deactivate_people_here_on_7db65233' => 'Дозвольте постачальнику автоматично створювати й деактивувати тут користувачів, щоб після звільнення людина втрачала доступ усюди без звернення до підтримки.',
    'list_at_least_one_origin_a_key_presentable_from_nowhere_71e6ca50' => 'Укажіть принаймні одне джерело: ключ, який не можна надати з жодного джерела, фактично відкликано. Натомість відкличте його.',
