    'point_claude_code_cursor_or_your_own_bot_at_this_enviro_7beb8319' => 'Спрямуйте Claude Code, Cursor або власного бота на MCP-сервер цього середовища. Позначається після першого виклику агента.',
    'provision_and_deprovision_their_people_over_scim_from_t_150caa32' => 'Створюйте й деактивуйте їхніх користувачів через SCIM із їхнього каталогу або кадрової системи.',
    'radar_now_enforces_blocks_refuse_challenges_ask_for_a_s_fe2c0317' => 'Radar тепер застосовує правила: блокування відмовляють у доступі, а додаткові перевірки вимагають підтвердження особи.',
