    'refuse_a_sign_in_the_platform_has_already_accepted_no_s_79c80cc5' => 'Відхилити вхід, який платформа вже прийняла. Сеанс не створюється.',
    'register_the_endpoint_and_choose_the_hook_point_it_answ_bd5f70f2' => 'Зареєструйте кінцеву точку й виберіть точку виклику, на яку вона відповідатиме.',
