    'reply_2xx_quickly_and_do_the_real_work_in_the_backgroun_90953132' => 'Швидко повертайте відповідь 2xx, а основну роботу виконуйте у фоновому режимі. Доставки повторюються, тому безпечно обробляйте дублікати.',
