    'whose_sign_ins_it_is_called_for_or_tick_environment_wid_38b9a155' => 'Для входів якої організації викликається — або позначте вище Усе середовище.',
    'create_a_key_for_claude_code_cursor_or_your_own_bot_giv_90d822be' => 'Створіть ключ для Claude Code, Cursor або власного бота. Надайте лише потрібні області доступу й визначте, які дії чекатимуть вашого схвалення.',
    'each_is_an_isolated_stage_production_or_sandbox_with_it_c8b3283a' => 'Кожне середовище — ізольований етап, робочий чи тестовий, із власними користувачами, ключами й входом. Передпродукційне середовище можна назвати «Staging».',
    'each_organization_is_a_company_or_team_using_your_produ_7719f059' => 'Кожна організація — це компанія чи команда, що використовує ваш продукт, із власними користувачами, ролями та єдиним входом. Створіть першу, щоб почати.',
    'every_administrative_change_members_roles_connections_a_ef641619' => 'Кожна адміністративна зміна учасників, ролей, підключень і застосунків одразу записується тут із зазначенням автора й часу. Налаштування не потрібне: записування автоматичне.',
    'every_member_is_signed_out_of_it_and_refused_at_every_d_67c21f22' => 'Сеанси всіх учасників завершуються, доступ усіма шляхами блокується, а застосунки перестають приймати їхні входи. Це неможливо скасувати з консолі.',
    'every_organization_in_the_target_environment_the_manage_9b4126ae' => 'Усі організації в цільовому середовищі: дерево керування реселерами, керованими ними організаціями та підрозділами.',
    'every_organization_s_people_are_pushed_to_this_one_targ_27734b94' => 'Люди з усіх організацій надсилаються до цього єдиного призначення. На відміну від вибору організації вище, це підключення охоплює все середовище.',
    'issue_a_fresh_token_the_one_your_identity_provider_hold_c37da34e' => 'Видайте новий токен. Токен, який зараз використовує постачальник ідентифікації, негайно перестає працювати. Після ротації одразу скопіюйте новий токен до постачальника ідентифікації.',
