    'anyone_who_has_not_migrated_yet_stops_being_able_to_sig_ed9f870a' => 'Ті, хто ще не мігрував, не зможуть входити, доки це не буде схвалено знову. Уже перенесених користувачів це не зачепить.',
    'asked_before_every_rule_a_deny_entry_blocks_an_allow_en_e80b3f61' => 'Перевіряється перед кожним правилом. Запис заборони блокує, а запис дозволу обходить усі правила, зокрема вбудовані. Якщо до однієї спроби застосовуються обидва записи, заборона має пріоритет.',
    'attach_this_to_the_iam_user_whose_access_key_the_stream_7659ba28' => 'Прикріпіть це до користувача IAM, чий ключ доступу використовує потік: йому буде дозволено лише записувати об’єкти під цим префіксом — без читання, перегляду списку чи видалення.',
