    'every_page_you_open_from_now_on_organizations_usage_org_7ba726d3' => 'Кожна сторінка, яку ви відтепер відкриєте — організації, використання й деталі організації — читатиме це середовище замість поточного. У жодному середовищі нічого не змінюється.',
    'everybody_d980065b' => 'Усі: ',
    'everyone_in_this_organization_is_refused_at_every_door_40e035a5' => 'Усі люди в цій організації негайно втрачають доступ усіма шляхами, а організація зникає зі списків. Це неможливо скасувати з консолі.',
    'framework_eea732d53f46' => 'Не вдалося прочитати конфігурацію OpenID постачальника — перевірте URL-адресу емітента. (:details)',
    'from_the_next_attempt_blocks_refuse_sign_ins_and_sign_u_e89996c3' => 'Починаючи з наступної спроби, блокування відхилятимуть входи й реєстрації в цьому середовищі, а додаткові перевірки вимагатимуть підтвердження особи. Помилкове правило може заблокувати справжніх користувачів.',
