    'groups_appear_here_after_the_first_sync_that_includes_t_d8006c0f' => 'Групи з’являються тут після першої синхронізації, що їх включає. Якщо постачальник фільтрує групи, які надсилає, список відображає цей фільтр.',
    'its_people_are_refused_at_every_door_sign_in_the_device_5c2c7648' => 'Доступ людей усіма шляхами — входом, потоком для пристроїв і екраном згоди — блокується до повторної активації. Нічого не видаляється.',
    'keys_this_organization_s_people_have_created_for_its_ap_9d7e0611' => 'Ключі, які люди цієї організації створили для її застосунків, із дозволами кожного ключа. Кожен створює власні; відкличте ключ, який витік або більше не використовується.',
    'let_an_organization_sign_in_with_okta_entra_id_or_googl_cf114dfb' => 'Дозвольте організації входити через Okta, Entra ID або Google Workspace чи надішліть її адміністратору посилання на Портал адміністратора, щоб він налаштував це сам.',
