    'stored_encrypted_and_never_shown_again_part1_2bdbba2d' => 'Зберігається зашифрованим і більше не показується. :part1',
    'the_admin_console_s_own_palette_as_hex_0a2540_or_oklch_71ec4917' => 'Власна палітра консолі адміністрування в шістнадцятковому форматі (#0a2540) або oklch(…). Сторінка входу бере кольори з теми вище.',
    'the_agent_is_refused_and_cannot_act_on_this_person_s_be_e1cd49d2' => 'Запит агента відхилено, і він не може діяти від імені людини. Відмову записано до журналу аудиту; її не можна скасувати, агент має запитати знову.',
    'the_agent_will_act_as_you_with_your_access_and_no_key_t_dd9fa746' => 'Агент діятиме від вашого імені з вашим доступом, без ключа, який потрібно зберігати. До того часу доступ надається ключем керування.',
    'the_current_signing_secret_stops_verifying_immediately_54edeb63' => 'Поточний секрет підпису негайно перестає підтверджувати підписи й не може бути відновлений. Одержувач відхиляє кожну доставку, доки його не оновлено.',
    'the_environment_default_inherited_by_every_organization_19ddab20' => 'Стандартний візуальний стиль середовища, який успадковують організації без власного. Власний стиль організації налаштовується на її сторінці у вкладці Візуальний стиль.',
    'the_secret_signs_every_delivery_s_hmac_it_is_stored_sea_830c30dd' => 'Секрет підписує кожну доставку через HMAC. Він зберігається зашифрованим і не може бути отриманий знову. Ротація видає новий секрет, який показується лише раз.',
    'the_site_your_account_lives_on_the_domain_of_the_datado_7f128cbf' => 'Сайт, на якому розміщено ваш обліковий запис: домен URL Datadog, де ви входите. Ключ API працює лише на своєму сайті.',
    'the_token_your_identity_provider_currently_holds_stops_5458b580' => 'Токен, який зараз використовує постачальник ідентифікації, негайно перестає працювати. Створення й оновлення облікових записів не працюватиме, доки ви не вставите там новий токен.',
    'pick_where_the_trail_goes_splunk_elastic_graylog_cef_or_e69f3c8f' => 'Виберіть, куди надсилати журнал: Splunk, Elastic, Graylog, CEF або будь-який колектор JSON, Datadog чи власний бакет Amazon S3 або Google Cloud Storage.',
    'register_an_app_so_your_people_can_sign_in_to_it_with_t_9fcc62a6' => 'Зареєструйте застосунок, щоб користувачі могли входити до нього з наявним тут обліковим записом. Саме цей крок дозволяє їм почати користуватися Cbox ID.',
    'session_ceiling_with_idle' => 'Максимальні ліміти цього розгортання — неактивність: :idle; загальна тривалість сеансу: :absolute (CBOX_ID_SESSION_IDLE_MINUTES, CBOX_ID_SESSION_TTL_MINUTES).',
    'shorter_than_today_events_older_than_this_are_deleted_f_8cf235f8' => 'Коротше за поточний строк: старіші події буде остаточно видалено під час наступного щоденного очищення для всіх організацій.',
    'that_approval_was_already_used_or_was_given_for_a_diffe_86a561c7' => 'Це схвалення вже використано або надано для іншого запиту. Повторіть запит без нього, щоб знову попросити схвалення.',
    'the_account_s_last_successful_sign_in_was_too_far_away_e6d46632' => 'Останній успішний вхід до облікового запису відбувся надто далеко й надто недавно, щоб устигнути дістатися звідти. Потрібна аналітика IP-адрес.',
    'the_address_belongs_to_a_hosting_provider_or_data_centr_213f7032' => 'Адреса належить хостинг-провайдеру або центру обробки даних, звідки люди рідко входять. Потрібна аналітика IP-адрес, яка це визначає.',
    'the_address_is_a_tor_exit_node_a_vpn_or_an_open_proxy_t_f7fc0d8a' => 'Адреса є вихідним вузлом Tor, VPN або відкритим проксі. Tor визначається за локальним списком виходів; для VPN і проксі потрібна відповідна аналітика IP-адрес.',
    'the_audit_events_the_app_records_about_this_organizatio_5a83961e' => 'Події аудиту, які застосунок записує про цю організацію, від найновіших. Лише читання: тут нічого не можна змінити.',
    'the_button_disappears_from_every_sign_in_page_in_this_e_c817a046' => 'Кнопка зникне з усіх сторінок входу цього середовища, які її успадковують. Облікові дані збережуться, тож її можна буде ввімкнути знову.',
    'the_console_is_pointed_at_this_environment_and_every_pa_4d2a0145' => 'Консоль перемикається на це середовище, і кожна сторінка, яку ви відтепер відкриватимете, читатиме його замість поточного. У жодному з них нічого не змінюється.',
    'the_risk_score_reached_its_reject_threshold_ip_reputati_e04e768d' => 'Оцінка ризику досягла порога відхилення: репутація IP, honeypot, агент користувача, MX та інші оцінювані сигнали.',
    'the_sign_in_page_your_people_see_is_yours_not_ours_logo_7573e3bf' => 'Сторінка входу використовує стиль вашої організації: логотип, кольори й тексти. Зміни одразу видно в попередньому перегляді, і вони застосовуються до розміщеної сторінки входу цієї організації.',
    'this_connection_belongs_to_the_environment_not_to_one_o_5e9a5366' => 'Це підключення належить середовищу, а не окремій організації. Установіть обов’язковість у Політиці автентифікації.',
    'this_connection_can_t_be_changed_while_the_organization_d78c4f4e' => 'Це підключення не можна змінити, поки організація не має тарифу Enterprise. Для активації зверніться до команди, яка обслуговує ваш обліковий запис.',
    'this_connection_s_settings_could_not_be_read_so_nothing_0ab248ca' => 'Не вдалося прочитати налаштування цього підключення, тому нічого не змінено. Спочатку повторно введіть налаштування постачальника ідентифікації.',
    'this_destroys_the_user_s_enrolled_second_factor_and_the_288206be' => 'Це видаляє зареєстрований другий фактор користувача та його коди відновлення. До повторної реєстрації обліковий запис захищатиме лише пароль.',
    'this_endpoint_belongs_to_the_environment_and_receives_e_f1dc8df9' => 'Ця кінцева точка належить середовищу й отримує події всіх організацій, включно з вашою. Нею керує оператор.',
    'this_environment_falls_back_to_its_default_domain_every_201d6a2d' => 'Це середовище повернеться до стандартного домену. Усі клієнти, прив’язані до поточного емітента, URL-адреси виявлення або URL-адреси JWKS, не працюватимуть до переналаштування.',
    'this_organization_s_brand_it_overrides_the_environment_ffdddbcc' => 'Візуальний стиль цієї організації замінює стандартний стиль середовища. Зміни одразу видно в попередньому перегляді, і вони застосовуються до розміщеної сторінки входу.',
    'this_provider_s_discovery_document_publishes_no_signing_07a38178' => 'Документ виявлення цього постачальника не публікує ключів підпису (jwks_uri). Вставте його ключ підпису токенів ID — відкритий ключ PEM.',
    'valid_once_and_short_lived_turn_this_off_only_if_you_ar_521114e3' => 'Дійсне один раз і недовго. Вимикайте лише тоді, коли створюєте обліковий запис заздалегідь і надішлете посилання самостійно.',
    'verify_the_domain_before_turning_capture_on_until_then_4ff9f310' => 'Підтвердьте домен, перш ніж увімкнути обов’язкове спрямування до SSO. До цього організація не довела, що ці адреси їй належать.',
    'verify_the_signature_on_every_call_and_answer_within_th_5219ed81' => 'Перевіряйте підпис кожного виклику й відповідайте до завершення тайм-ауту: це виконується, поки людина чекає на екрані входу.',
    'paste_the_full_service_account_json_key_it_m_9ffc8f83' => 'Вставте повний JSON-ключ облікового запису служби; він має містити client_email і private_key.',
    'this_browser_cannot_create_a_passkey_so_ther_2fac1ac0' => 'Цей браузер не може створити ключ доступу, тому тут не можна додати новий. Наявні ключі наведено нижче, і їх можна видалити.',
    'they_lose_this_role_in_every_organization_at_once_apps_2750f7e3' => 'Людина втрачає цю роль у всіх організаціях одночасно. Поточні перевірки авторизації враховують зміну під час наступної захищеної дії; дані наявних токенів відображають стан на момент видачі. Нікого не буде виведено із сеансу.',
    'they_lose_this_role_in_every_organization_at_once_apps_39477fda' => 'Людина втрачає цю роль у всіх організаціях одночасно. Поточні перевірки авторизації враховують зміну під час наступної захищеної дії; дані наявних токенів відображають стан на момент видачі. Нікого не буде виведено із сеансу.',
    'a_management_key_acts_in_its_own_environment_only_expor_d9ba3890' => 'Ключ керування діє лише у власному середовищі. Експортуйте шаблон застосунку (GET /apps/{id}/blueprint) і зареєструйте його ключем іншого середовища (POST /apps із `blueprint`).',
    'choose_scim_if_your_provider_pushes_to_us_google_worksp_99b715bb' => 'Виберіть SCIM, якщо постачальник надсилає дані нам, Google Workspace або Entra, якщо їх маємо отримувати ми, або свою кадрову систему — Workday, BambooHR, Rippling, HiBob чи Personio — щоб люди з’являлися в день початку роботи.',
    'puts_the_keys_of_the_feature_flags_that_are_on_for_the_70599dc3' => 'Додає ключі прапорців функцій, увімкнених для людини в організації, до якої вона ввійшла, до токена доступу, токена ID та UserInfo як твердження `feature_flags`.',
    'the_button_disappears_from_this_organization_s_sign_in_88a1cc4f' => 'Кнопка зникне зі сторінки входу цієї організації; власна кнопка середовища її не замінить. Облікові дані збережуться, тож кнопку можна буде ввімкнути знову.',
    'this_credential_needs_a_person_s_approval_for_this_acti_6e7eed81' => 'Ці облікові дані потребують схвалення людини для цієї дії, але такої людини не зареєстровано. Виконайте дію з консолі або створіть у консолі ключ, власник якого зможе її схвалити.',
    'this_endpoint_belongs_to_the_environment_and_fires_for_2bbbb6fd' => 'Ця кінцева точка належить середовищу й виконується для кожної його організації. Вона показана тут, бо бере участь у ваших входах; нею керує оператор.',
    'we_could_not_send_the_email_right_now_this_deployment_c_03e046b9' => 'Зараз не вдалося надіслати лист: це розгортання не може з’єднатися з поштовим сервером. Спробуйте пізніше. Адміністратор також може підтвердити адресу командою `php artisan cbox-id:users:confirm-email`.',
    'when_an_app_or_agent_needs_your_go_ahead_to_act_as_you_3a85a2a9' => 'Коли застосунку чи агенту потрібна згода на дії від вашого імені, він запитує її тут. Схвалюйте лише запити, які ви самі розпочали.',
    'whether_the_background_work_of_this_install_webhooks_si_0647da12' => 'Перевірте, чи справді надсилаються фонові завдання цього встановлення: вебхуки, сповіщення про вихід до підключених застосунків і листи в черзі.',
    'you_need_credentials_from_your_own_account_with_the_pro_6556573b' => 'Потрібні облікові дані вашого власного облікового запису в постачальника, зазвичай ID та секрет клієнта. Apple натомість видає ключ підпису.',
    'your_endpoint_is_called_in_the_middle_of_an_operation_a_ab67a6b0' => 'Ваша кінцева точка викликається під час операції, і її відповідь змінює результат: може додати дані до токена або відмовити у вході.',
    'your_endpoints_get_a_signed_message_after_something_hap_04723db4' => 'Кінцеві точки отримують підписане повідомлення після події, щоб системи могли реагувати без постійного опитування.',
    'your_organization_s_name_domains_and_defaults_changes_h_8e3220c0' => 'Назва, домени й стандартні налаштування організації. Зміни застосовуються до всіх, хто входить через цю організацію.',
    'your_own_credentials_with_each_provider_offered_on_ever_82ce1e08' => 'Ваші власні облікові дані в кожного постачальника, доступні на всіх сторінках входу цього середовища. Усі його організації їх успадковують.',
    'your_own_credentials_with_each_provider_offered_to_ever_d1715d1a' => 'Ваші власні облікові дані в кожного постачальника, доступні всім у цьому середовищі. Кожна організація їх успадковує.',
    'your_receiver_keeps_the_same_secret_used_exactly_as_wri_431d83f5' => 'Одержувач зберігає той самий секрет і використовує його точно в записаному вигляді, включно з префіксом whsec_, як ключ HMAC для X-Cbox-Signature.',
    'your_sign_in_page_carries_your_logo_and_colours_people_76d3ce22' => 'Ваша сторінка входу має ваш логотип і кольори. Люди вводять на ній пароль, тож вона має представляти вас, а не нас.',
    'your_organization_its_projects_team_keys_and_billing_si_152a2f42' => 'Ваш робочий простір: проєкти, команда, ключі й оплата. Вхід до застосунків налаштовується в консолі кожного середовища.',
    'a_management_key_reads_and_writes_this_envir_aba5f345' => 'Ключ керування читає та змінює організації й користувачів цього середовища через API; його значення показується лише один раз.',
    'you_hold_no_permissions_in_part1_so_a_key_would_identif_2c680207' => 'У вас немає дозволів у :part1, тому ключ лише ідентифікував би вас і більше нічого не дозволяв.',
    'only_what_you_can_do_in_part1_yourself_is_offered_if_yo_54637548' => 'Доступні лише дії, які ви самі можете виконувати в :part1. Якщо згодом ви втратите дозвіл, ключ також його втратить.',
    'scope_part1_removed_apps_that_held_it_keep_it_as_a_type_7572a80d' => 'Область доступу «:part1» видалено. Застосунки, які її мали, зберігають її як введену вручну область, що більше не надає доступу до цього API.',
    'feature_flag_part1_deleted_apps_asking_for_it_now_get_o_bf0ceaac' => 'Прапорець функції «:part1» видалено. Застосунки, які його запитують, тепер отримують вимкнений стан.',
    'feature_flag_part1_created_it_is_off_for_everyone_until_32603be3' => 'Прапорець функції «:part1» створено. Він вимкнений для всіх, доки його не ввімкне правило нижче або типове значення.',
    'webhook_subscribed_events_count' => 'Події за підпискою: :count',
    'sms_enabled_country_count' => 'Коди через SMS увімкнено. Дозволені країни: :count.',
    'showing_part1_of_part2_type_to_narrow_54c3f471' => 'Показано :part1 із :part2. Введіть текст, щоб звузити результати.',
    '_part1_of_part2_actions_shown_part3_chosen_69e741ea' => 'Показані дії: :part1 із :part2 · вибрані: :part3',
    'the_people_on_part1_and_what_each_may_reach_474ab0a4' => 'Люди в організації :part1 та ресурси, до яких кожен має доступ.',
    'each_link_opens_part1_in_that_environment_s_console_5f38b7b2' => 'Кожне посилання відкриває сторінку «:part1» у консолі відповідного середовища.',
    'unchanged_by_anything_here_so_nothing_to_update_in_part_75ac8c0d' => 'Ніщо на цій сторінці не змінює цей URI, тому в :part1 нічого оновлювати не потрібно.',
    'risk_score_part1_part2_recorded_under_part3_part4_ae0bca2b' => 'Оцінка ризику: :part1 (:part2) · режим під час запису: :part3 :part4',
    'exactly_as_shown_part1_stays_disabled_until_it_matches_fa10ae07' => 'Введіть точно показаний текст. Кнопка «:part1» залишатиметься неактивною, доки текст не збігатиметься.',
    'puts_the_person_s_roles_on_the_id_token_under_the_name_1df84dc6' => 'Додає РОЛІ людини до токена ID під назвою `groups`, яку очікують Kubernetes, Grafana, Vault і більшість старіших SaaS. У цій консолі немає поняття групи: створіть Роль із назвою, яку очікує застосунок, і вона з’явиться тут.',
    'that_favicon_cannot_be_used_send_the_image_itself_as_a_96450fb1' => 'Цю піктограму сайту не можна використати. Надішліть саме зображення як URI data: у base64 (data:image/png;base64,…). URL-адреси зовнішніх зображень не приймаються: кожен відвідувач завантажує зображення сторінки входу, а зовнішня адреса повідомила б її серверу, хто ці відвідувачі.',
    'that_logo_cannot_be_used_send_the_image_itself_as_a_bas_ae6a22d5' => 'Цей логотип не можна використати. Надішліть саме зображення як URI data: у base64 (data:image/png;base64,…). URL-адреси зовнішніх зображень не приймаються: кожен відвідувач завантажує зображення сторінки входу, а зовнішня адреса повідомила б її серверу, хто ці відвідувачі.',
    'approving_or_withdrawing_a_legacy_login_chan_af2b50b3' => 'Схвалення або відкликання входу через стару систему змінює напрямок запитів на вхід.',
    'connecting_a_directory_issues_a_bearer_token_c946f8c1' => 'Підключення каталогу створює bearer-токен для створення й оновлення облікових записів користувачів. Його буде показано лише раз на наступному екрані.',
    'copying_an_app_registers_it_in_another_envir_b6eb3523' => 'Копіювання застосунку реєструє його в іншому середовищі з новим секретом клієнта, який буде показано лише раз на наступному екрані.',
    'creating_an_app_issues_a_client_secret_shown_2840959a' => 'Створення застосунку видає секрет клієнта, показаний лише раз на наступному екрані; до ротації він дозволяє автентифікуватися як цей застосунок.',
    'each_redirect_uri_must_use_https_http_is_all_5445c31e' => 'Кожна URI-адреса перенаправлення має використовувати https (http дозволено лише на localhost), наприклад https://app.example.com/callback.',
    'each_sign_out_uri_must_use_https_http_is_all_b9c71673' => 'Кожна URI-адреса виходу має використовувати https (http дозволено лише на localhost), наприклад https://app.example.com/signed-out.',
    'erasing_a_person_deletes_their_credentials_m_0c49a669' => 'Видалення користувача остаточно видаляє його облікові дані, членства й персональні дані. Відновити їх неможливо.',
    'every_primitive_the_console_is_built_from_sw_f2daecc0' => 'Усі базові компоненти, з яких побудована консоль. Перемкніть тему й звузьте вікно: набір тестів не може візуально оцінити жодну з цих змін.',
    'everything_an_admin_can_do_and_the_only_one__170b2916' => 'Може робити все, що адміністратор, і лише він може видалити організацію або передати право власності на неї.',
