    'registering_an_app_issues_a_client_secret_sh_631bb9f1' => 'Реєстрація застосунку видає секрет клієнта, показаний лише раз на наступному екрані; до ротації він дозволяє автентифікуватися як цей застосунок.',
    'registering_an_endpoint_issues_a_signing_sec_d3094c17' => 'Реєстрація кінцевої точки видає секрет підпису й починає надсилання подій у реальному часі.',
    'removing_this_phone_number_may_leave_the_use_76d23e13' => 'Видалення цього номера телефону може залишити користувача захищеним лише паролем.',
    'replacing_the_credentials_changes_whose_acce_323a6d4c' => 'Заміна облікових даних змінює ідентичність, чий доступ використовується для створення й деактивації облікових записів цих користувачів.',
    'resetting_two_factor_leaves_this_user_protec_1f98fc48' => 'Скидання двофакторної автентифікації залишає цього користувача захищеним лише паролем.',
    'revoking_a_management_key_stops_whatever_is__07f06719' => 'Відкликання ключа керування негайно зупиняє все, що його використовує.',
    'revoking_a_secret_stops_it_working_immediate_0f24d7b4' => 'Відкликання секрету негайно робить його недійсним; усе, що ще його використовує, не зможе автентифікуватися.',
    'revoking_an_organization_key_stops_whatever__fd3cd5f4' => 'Відкликання ключа організації негайно зупиняє все, що його використовує.',
    'rotating_a_management_key_mints_its_successo_3bb1cc71' => 'Ротація ключа керування створює його наступника, значення якого показується лише один раз.',
    'selected_permissions_count' => 'Вибрані дозволи: :count',
    'sso_required_organization' => 'Для організації :organization обов’язковий корпоративний SSO. Усі інші способи входу заблоковано, доки цю вимогу не буде змінено в розділі «:policy».',
    'sso_required_environment' => 'Для цього середовища обов’язковий корпоративний SSO. Усі інші способи входу заблоковано, доки цю вимогу не буде змінено в розділі «:policy».',
    'someone_who_part1_is_never_sent_their_password_is_the_o_6e557319' => 'Вхід користувача, який :part1, ніколи не надсилається до старої системи. Діє його пароль у Cbox ID, а стара система не бере участі в автентифікації.',
    'if_that_endpoint_is_part1_people_who_have_not_migrated_18fc0415' => 'Якщо ця кінцева точка :part1, користувачі, яких ще не перенесено, не можуть увійти. Уже перенесених це не зачіпає.',
    'every_session_in_this_organization_ends_part1_part2_b33262fc' => 'Усі сеанси в цій організації завершуються — :part1 :part2.',
    'the_same_code_step_by_step_with_sign_out_part1_part2_4d2f071e' => 'Той самий код крок за кроком, включно з виходом: :part1 :part2.',
    'the_newest_entries_on_part1_s_trail_dac97d7d' => 'Найновіші записи в журналі аудиту організації :part1.',
    '_part1_refuses_the_sign_in_unless_this_matches_exactly_8d9cdd26' => ':part1 відмовляє у вході, якщо значення не збігається точно. Воно зарезервоване для цього налаштування, тому можна зараз вставити його в :part2, а тут зберегти пізніше.',
    '_part1_sessions_passkeys_and_second_factors_identity_pr_1ab27bf9' => ':part1 — сеанси, ключі доступу, другі фактори, профілі постачальників ідентифікації, дані каталогів, видані токени, призначення ролей та історія аудиту зберігаються. Людину можна активувати знову.',
    '_part1_things_worth_doing_roughly_in_this_order_each_on_b3e154c4' => 'Рекомендовані кроки: :part1, приблизно в такому порядку. Кожен позначається автоматично, коли справді виконаний; нічого не потрібно вручну позначати завершеним.',
    '_part1_this_console_is_not_signed_in_to_with_them_admin_a3d216ed' => ':part1 Ці методи не використовуються для входу в цю консоль. Адміністратори входять через Cbox ID за адресою :part2, використовуючи його методи входу.',
    'a_management_key_for_one_agent_it_can_do_only_what_its_e35f0a5f' => 'Ключ керування для одного агента. Він може робити лише те, що дозволяють його області доступу, а вибрані вами дії чекають схвалення на телефоні або тут: :part1.',
    'a_part1_is_one_product_s_idp_it_holds_isolated_part2_pa_c2f6b974' => ':part1 — це постачальник ідентифікації одного продукту з окремим тарифом. Він містить ізольовані :part2 :part3, робочі й тестові, кожне з власними користувачами, ключами та входом.',
    'an_organization_key_reaches_the_organization_itself_pro_0257779c' => 'Ключ організації надає доступ до самої організації — проєктів, середовищ, команди й ключів — а не всередину середовища. Створіть його на кореневому рівні платформи в розділі :part1 :part2 :part3.',
    'applications_that_trust_this_environment_as_their_saml_0e2642cf' => 'Застосунки, які довіряють цьому середовищу як постачальнику ідентифікації SAML. Для входу з уже наявними обліковими записами інших сервісів використовуйте :part1 :part2.',
    'approvals_cover_the_management_api_s_actions_these_scop_3eade41d' => 'Схвалення охоплюють дії API керування. Ці області доступу обслуговують кінцеві точки, які ще не є діями, тому вони виконуються без запиту на схвалення: :part1 :part2.',
    'rotating_this_app_s_secret_creates_a_new_one_c5772a3d' => 'Ротація секрету цього застосунку створює новий і негайно робить поточний недійсним.',
    'rotating_this_directory_s_bearer_token_stops_5f1d734c' => 'Ротація bearer-токена цього каталогу зупиняє токен у постачальника ідентифікації, доки ви не вставите туди новий.',
    'setting_a_password_replaces_this_person_s_cr_d729ce98' => 'Задання пароля замінює облікові дані цієї людини; параметр «показати» дозволяє його побачити.',
    'signing_in_to_an_app_as_this_person_lets_you_11b85bdb' => 'Вхід до застосунку як ця людина дозволяє вам діяти там від її імені.',
    'signs_in_to_the_organization_s_apps_no_conso_29e90a33' => 'Входить до застосунків організації. Без адміністрування консолі.',
    'that_code_did_not_match_or_it_has_expired_tr_b6366c59' => 'Код не збігається або термін його дії минув. Спробуйте знову чи надішліть новий.',
    'that_prefix_is_reserved_for_cbox_id_s_own_ke_ae985061' => 'Цей префікс зарезервовано для власних ключів Cbox ID. Виберіть інший.',
    'the_current_secret_stops_working_immediately_a6493eff' => 'Поточний секрет негайно перестане працювати. Усе, що ще використовує його для перевірки, почне відхиляти доставки.',
    'the_environment_baseline_is_what_organizatio_21fbaea3' => 'Організації успадковують базові налаштування середовища; самі базові налаштування нічого не успадковують.',
    'the_environment_this_deployment_itself_runs__4fdb5a7a' => 'Середовище, у якому працює саме розгортання: тут входять оператори й команди організацій. Воно не належить жодній організації.',
    'the_export_disk_must_be_storage_every_web_an_2d6bfbff' => 'Диск експорту має бути спільним для всіх вебпроцесів і воркерів; виконайте `php artisan cbox-id:doctor`.',
    'there_is_no_other_environment_in_this_projec_bfd62f34' => 'У цьому проєкті немає іншого середовища, яке ви адмініструєте. Додайте його до проєкту або попросіть доступ, і воно з’явиться тут.',
    'this_acts_on_one_organization_and_none_is_na_3ad67fdd' => 'Ця дія стосується однієї організації, але тут жодну не вказано. Відкрийте її зі сторінки самої організації.',
    'this_app_belongs_to_an_organization_and_an_o_5487ac51' => 'Цей застосунок належить організації, а організація існує лише в одному середовищі. Завантажте шаблон застосунку й зареєструйте його в іншому середовищі під організацією, якій він там належить.',
    'this_app_registered_itself_so_it_is_not_one__ec7cea33' => 'Цей застосунок зареєструвався самостійно, тож не є власним застосунком цього середовища. Він може так само зареєструватися в іншому середовищі.',
    'this_app_signs_in_with_its_own_keys_and_each_a40a0c9b' => 'Цей застосунок автентифікується власними ключами, а кожне середовище має мати свої. Завантажте шаблон і зареєструйте його в іншому середовищі з набором ключів того середовища.',
    'this_belongs_to_the_environment_and_is_admin_c17de890' => 'Належить середовищу й адмініструється з його консолі.',
    'this_endpoint_belongs_to_the_environment_you_1c2b35cf' => 'Ця кінцева точка належить середовищу. Нею керує ваш оператор.',
    'too_many_codes_have_been_sent_wait_a_few_min_87e86ab7' => 'Надіслано забагато кодів. Зачекайте кілька хвилин і спробуйте знову.',
    'use_2_to_16_lowercase_letters_or_digits_star_cda1343d' => 'Використайте від 2 до 16 малих літер або цифр, починаючи з літери, а потім _live чи _test, наприклад acme_live.',
    'use_an_absolute_url_with_a_host_and_no_fragm_134d4387' => 'Використайте абсолютну URL-адресу з хостом, без фрагмента, завдовжки щонайбільше 255 символів, наприклад https://api.example.com.',
    'we_could_not_send_the_text_message_check_the_ad67f38a' => 'Не вдалося надіслати текстове повідомлення. Перевірте номер і спробуйте знову.',
    'we_fetch_a_short_lived_token_from_the_app_be_7b50ead6' => 'Перед кожним пакетом ми отримуємо від застосунку короткотривалий токен. Потрібні URL-адреса токена й ідентифікатор клієнта.',
    'whether_a_feature_is_switched_on_for_someone_631c0d5f' => 'Чи ввімкнено функцію для людини. Це поступове впровадження, а не контроль доступу; ніколи не захищайте цим дані.',
    'who_may_do_what_to_which_record_your_app_wri_ca6c6d61' => 'Хто що може робити з яким записом. Ваш застосунок записує зв’язки й запитує перевірку для кожного запиту.',
    'organization_created_but_the_owner_could_not_21800822' => 'Робочий простір створено, але власнику не вдалося надіслати посилання. Попросіть його скористатися функцією «Забули пароль».',
    'you_appear_to_be_offline_check_your_connecti_0d700f8e' => 'Схоже, ви не в мережі. Перевірте з’єднання й спробуйте знову.',
    'you_re_signed_in_you_don_t_belong_to_an_orga_67d0efb9' => 'Ви ввійшли. Тут ви ще не належите до жодної організації; обліковий запис і налаштування безпеки залишаються під вашим контролем.',
    'app_keys_unavailable_organization_switch' => 'Застосунок, який спрямував вас сюди, не надає API-ключів для організації :organization. Спробуйте іншу організацію або зверніться до підтримки застосунку.',
    'app_keys_unavailable_organization' => 'Застосунок, який спрямував вас сюди, не надає API-ключів для організації :organization. Зверніться до підтримки застосунку.',
    'app_keys_unavailable_switch' => 'Застосунок, який спрямував вас сюди, не надає API-ключів. Спробуйте іншу організацію або зверніться до підтримки застосунку.',
    'app_keys_unavailable' => 'Застосунок, який спрямував вас сюди, не надає API-ключів. Зверніться до підтримки застосунку.',
    'connect_once_at_the_platform_root_instead_of_once_per_e_df000287' => 'Підключіться один раз на кореневому рівні платформи, а не окремо для кожного середовища. Агент, що ввійшов від вашого імені, має доступ до організації, усіх її середовищ, якими ви керуєте, та вашого облікового запису. Місце дії задає аргумент :part1 :part2 для інструмента середовища або заголовок :part3 для REST API. Агент може робити те саме, що й ви, у дозволених межах; кожна критична дія чекає схвалення на вашому пристрої.',
    'each_organization_gives_them_one_part1_what_they_may_ad_69f922a2' => 'Кожна організація надає людині одну роль типу :part1, яка визначає її можливості адміністрування, і будь-яку кількість ролей типу :part2, які визначають можливості в застосунках.',
    'environment_part1_created_add_part2_from_the_environmen_9b25a836' => 'Середовище «:part1» створено. Додайте :part2 у налаштуваннях доменів середовища для перевірки через DNS. Непідтверджений домен не може бути видавцем середовища.',
    'environments_nest_under_a_project_and_a_project_under_a_a7f5aa8e' => 'Середовища належать проєкту, а проєкт — організації (:part1 :part2 :part3). Почніть там, щоб побачити всі її ресурси. Два типи записів ніколи не мають організації: :part4 — це середовище самого встановлення, де розміщені оператори та люди організацій; середовище з позначкою :part5 :part6 не має проєкту, тому не оплачується й жодна організація не має до нього доступу. Це не помилки для виправлення на цьому екрані, і він не змінює їхню належність.',
    'every_way_people_sign_in_to_part1_whether_it_is_on_and_4dda4364' => 'Усі способи входу до :part1, їхній стан і місце зміни. Організації можуть посилювати ці правила: :part2 :part3.',
