    'paste_the_whole_json_key_file_of_a_service_account_gran_6f4e93cd' => 'Вставте весь JSON-файл ключа службового облікового запису з роллю roles/storage.objectCreator для bucket. Зберігається зашифрованим і більше не показується. :part1',
