    'sandbox_environments_allow_localhost_urls_and_never_sen_299fef2d' => 'Тестові середовища дозволяють URL-адреси localhost і ніколи не надсилають справжніх листів. Залишок середовищ у тарифі цього проєкту: :part1.',
    'sign_in_to_one_of_your_apps_as_part1_to_see_what_they_s_1c96b645' => 'Увійдіть у застосунок як :part1, щоб побачити те саме, що й ця людина. Застосунок знає, що дієте ви, а журнал аудиту організації записує хто, коли й чому.',
    'someone_who_signs_in_and_is_part1_has_their_email_and_p_07a25128' => 'Коли людина намагається ввійти й має стан :part1, її електронна адреса й пароль надсилаються до цієї кінцевої точки. Якщо вона підтвердить вхід, людину буде створено тут, а дані більше не надсилатимуться туди.',
