    'the_role_part1_belongs_to_one_organization_and_cannot_b_e2bba059' => 'Роль [:part1] належить одній організації й не може бути надана всюди.',
    'the_role_part1_cannot_be_held_in_this_organization_it_b_6fdeacd4' => 'Роль [:part1] не може діяти в цій організації: вона належить іншій організації або застосунку, який ця організація не може використовувати.',
