    'what_you_are_administering_and_the_details_your_apps_ne_23bc71ef' => 'Те, що ви адмініструєте, і відомості, потрібні застосункам для інтеграції. :part1',
    'when_an_agent_s_key_needs_approval_for_an_action_the_re_56c5e366' => 'Коли ключ агента потребує схвалення дії, запит з’являється тут і на телефоні людини, яка створила ключ. Максимальний час очікування: :part1.',
    'your_endpoint_verifies_the_part1_header_on_each_request_b7ca1bb8' => 'Ваша кінцева точка використовує цей секрет для перевірки заголовка :part1 у кожному запиті.',
    'in_the_order_people_see_them_turning_one_of_the_environ_390888a5' => 'У порядку, в якому їх бачать люди. Вимкнення постачальника середовища тут лише прибирає кнопку із цієї сторінки; воно не заважає входити через нього деінде. Щоб залишити тільки вашого постачальника, вимагайте SSO в :part1 :part2.',
    'its_part1_can_no_longer_sign_in_to_this_organization_an_9a6e499c' => 'Люди, яких стосується зміна (:part1), більше не можуть входити до цієї організації, а застосунки, що залежать від неї, перестають їх автентифікувати. Дочірні організації не призупиняються. Організацію можна активувати знову тут.',
    'keys_start_with_it_so_a_key_found_in_a_log_names_this_a_8a69e3c2' => 'Ключі починаються із цього префікса, тому знайдений у журналі ключ указує застосунок: :part1 :part2. Використовуйте 2–16 малих літер або цифр, а потім :part3 чи :part4 :part5, унікально в середовищі. Задання вмикає ключі; очищення зупиняє нові, але наявні працюють до відкликання.',
    'nobody_in_this_organization_has_created_a_key_for_one_o_d0240315' => 'Ніхто в цій організації не створив ключ для її застосунків. Люди створюють власні в розділі Мій обліковий запис для застосунку, який у Налаштуваннях вмикає API-ключі учасників: :part1.',
